static const char *agfx_mmio_offset_name(uint64_t offset)
{
    switch ((uint32_t)offset) {
    case PVG_REG_FIFO_ENABLE:
        return "FIFO_ENABLE";
    case PVG_REG_FIFO_SIZE:
        return "FIFO_SIZE";
    case PVG_REG_FIFO_WRITE:
        return "FIFO_WRITE";
    case PVG_REG_FIFO_READ:
        return "FIFO_READ";
    case PVG_REG_FIFO_OFFSET:
        return "FIFO_OFFSET";
    case PVG_REG_SHARED_STATE_PFN:
        return "SHARED_STATE_PFN";
    case PVG_REG_KICK:
        return "KICK";
    case PVG_REG_EVENT_STAMPS:
        return "EVENT_STAMPS";
    case PVG_REG_DISPLAY_IRQ:
        return "DISPLAY_IRQ";
    case PVG_REG_PENDING_COMP:
        return "PENDING_COMP";
    case PVG_REG_TRANSACTION_ID:
        return "TRANSACTION_ID";
    case PVG_REG_FAULT_STATUS:
        return "FAULT_STATUS";
    case PVG_REG_FIFO_PFN:
        return "FIFO_PFN";
    case PVG_REG_PROTOCOL_VERSION:
        return "PROTOCOL_VERSION";
    case PVG_REG_IOSFC_ENABLE:
        return "IOSFC_ENABLE";
    case PVG_REG_IOSFC_CAPS:
        return "IOSFC_CAPS";
    case PVG_REG_IOSFC_CMD:
        return "IOSFC_CMD";
    case PVG_REG_IOSFC_DATA:
        return "IOSFC_DATA";
    case PVG_REG_IOSFC_TASK_PFN:
        return "IOSFC_TASK_PFN";
    case PVG_REG_IOSFC_TASK_SIZE:
        return "IOSFC_TASK_SIZE";
    case PVG_REG_IOSFC_MAP_FLAGS:
        return "IOSFC_MAP_FLAGS";
    case PVG_REG_IOSFC_MAP_ADDR:
        return "IOSFC_MAP_ADDR";
    case PVG_REG_IOSFC_UNMAP:
        return "IOSFC_UNMAP";
    case PVG_REG_IOSFC_UNMAP_LEN:
        return "IOSFC_UNMAP_LEN";
    case PVG_REG_IOSFC_RESULT:
        return "IOSFC_RESULT";
    case PVG_REG_DISPLAY_PORT_COUNT:
        return "DISPLAY_PORT_COUNT";
    default:
        return "OTHER";
    }
}

static bool agfx_mmio_roundtrip_interesting(uint64_t offset)
{
    if (agfx_mmio_all_on()) {
        return true;
    }

    switch ((uint32_t)offset) {
    case PVG_REG_FIFO_WRITE:
    case PVG_REG_FIFO_READ:
    case PVG_REG_KICK:
    case PVG_REG_EVENT_STAMPS:
    case PVG_REG_DISPLAY_IRQ:
    case PVG_REG_PENDING_COMP:
    case PVG_REG_TRANSACTION_ID:
        return true;
    default:
        return false;
    }
}

static void agfx_log_mmio_roundtrip(AppleGfxMLState *s, const char *where,
                                    uint64_t offset, uint64_t value,
                                    unsigned size, AppleGfxMLSessionJob *job)
{
    if (!agfx_mmio_roundtrip_on() ||
        !agfx_mmio_roundtrip_interesting(offset)) {
        return;
    }

    agfx_log(s,
             "[apple-gfx-ml] DIAG_MMIO_ROUNDTRIP where=%s ts_ns=%llu "
             "tid=0x%lx job=%p off=0x%llx reg=%s value=0x%llx size=%u "
             "mmio_wait=%d\n",
             where,
             (unsigned long long)subk_sig_timing_now_ns(),
             subk_sig_timing_tid(),
             (void *)job,
             (unsigned long long)offset,
             agfx_mmio_offset_name(offset),
             (unsigned long long)value,
             size,
             s ? qatomic_read(&s->mmio_wait_active) : -1);
}

static uint64_t agfx_env_u64(const char *name, uint64_t fallback)
{
    const char *env = getenv(name);
    char *end = NULL;
    uint64_t value;

    if (!env || !env[0]) {
        return fallback;
    }
    value = strtoull(env, &end, 0);
    return end != env ? value : fallback;
}

static bool agfx_guest_sched_sync_pc_for_mmio(AppleGfxMLState *s,
                                              uint64_t offset,
                                              uint64_t value,
                                              bool is_write)
{
    const char *env = getenv("QMU_DIAG_GUEST_SCHED_SYNC_PC");
    uint64_t interval;
    uint64_t min_interval;
    uint64_t max_interval;

    if (!env || !env[0] || strcmp(env, "0") == 0) {
        return false;
    }
    if (!s || !agfx_guest_sched_callsite_interesting(offset)) {
        return false;
    }

    interval = qatomic_read(&s->guest_sched_ch5_interval_id);
    if (is_write && offset == PVG_REG_KICK && value == 5) {
        interval++;
    }
    min_interval = agfx_env_u64("QMU_DIAG_GUEST_SCHED_SYNC_MIN_CH5", 0);
    max_interval = agfx_env_u64("QMU_DIAG_GUEST_SCHED_SYNC_MAX_CH5",
                                UINT64_MAX);
    if (interval < min_interval || interval > max_interval) {
        return false;
    }

    if (offset == PVG_REG_KICK) {
        if (value == 5) {
            return true;
        }
        if (agfx_guest_sched_sync_render_boundary_for_kick(s, interval, value)) {
            return true;
        }
        if (getenv("QMU_DIAG_GUEST_SCHED_SYNC_KICK5_ONLY")) {
            return false;
        }
        return true;
    }
    if (getenv("QMU_DIAG_GUEST_SCHED_SYNC_READS") &&
        !is_write &&
        (offset == PVG_REG_EVENT_STAMPS || offset == PVG_REG_DISPLAY_IRQ)) {
        return true;
    }
    if (getenv("QMU_DIAG_GUEST_SCHED_SYNC_FIFO") &&
        (offset == PVG_REG_FIFO_WRITE || offset == PVG_REG_FIFO_READ)) {
        return true;
    }
    return false;
}

