static uint32_t agfx_guest_sched_metal_author_kind(void)
{
    const char *env = getenv("QMU_DIAG_GUEST_SCHED_METAL_SEG_AUTHOR_KIND");

    if (!env || !env[0] || strcmp(env, "ioadd") == 0) {
        return AGFX_METAL_AUTHOR_KIND_IOADD;
    }
    if (strcmp(env, "reset") == 0) {
        return AGFX_METAL_AUTHOR_KIND_RESET;
    }
    if (strcmp(env, "mtladd") == 0 || strcmp(env, "mtl_add") == 0) {
        return AGFX_METAL_AUTHOR_KIND_MTL_ADD;
    }
    if (strcmp(env, "begin") == 0 || strcmp(env, "begin_segment") == 0) {
        return AGFX_METAL_AUTHOR_KIND_BEGIN_SEGMENT;
    }
    if (strcmp(env, "end") == 0 || strcmp(env, "end_segment") == 0) {
        return AGFX_METAL_AUTHOR_KIND_END_SEGMENT;
    }
    if (strcmp(env, "end_store") == 0 ||
        strcmp(env, "end_segment_store") == 0) {
        return AGFX_METAL_AUTHOR_KIND_END_SEGMENT_STORE;
    }
    if (strcmp(env, "finalize") == 0) {
        return AGFX_METAL_AUTHOR_KIND_FINALIZE;
    }
    if (strcmp(env, "alloc") == 0 || strcmp(env, "alloc_resource") == 0) {
        return AGFX_METAL_AUTHOR_KIND_ALLOC_RESOURCE;
    }
    if (strcmp(env, "custom") == 0) {
        return AGFX_METAL_AUTHOR_KIND_CUSTOM;
    }
    return AGFX_METAL_AUTHOR_KIND_IOADD;
}

static const char *agfx_guest_sched_metal_author_kind_name(uint32_t kind)
{
    switch (kind) {
    case AGFX_METAL_AUTHOR_KIND_BEGIN_SEGMENT:
        return "begin_segment";
    case AGFX_METAL_AUTHOR_KIND_END_SEGMENT:
        return "end_segment";
    case AGFX_METAL_AUTHOR_KIND_END_SEGMENT_STORE:
        return "end_segment_store";
    case AGFX_METAL_AUTHOR_KIND_MTL_ADD:
        return "mtl_add";
    case AGFX_METAL_AUTHOR_KIND_FINALIZE:
        return "finalize";
    case AGFX_METAL_AUTHOR_KIND_ALLOC_RESOURCE:
        return "alloc_resource";
    case AGFX_METAL_AUTHOR_KIND_IOADD:
        return "ioaccel_add";
    case AGFX_METAL_AUTHOR_KIND_RESET:
        return "ioaccel_reset";
    case AGFX_METAL_AUTHOR_KIND_CUSTOM:
        return "custom";
    default:
        return "unknown";
    }
}

static uint64_t agfx_guest_sched_metal_author_default_addr_for_kind(
    uint32_t kind)
{
    switch (kind) {
    case AGFX_METAL_AUTHOR_KIND_BEGIN_SEGMENT:
        return AGFX_METAL_BEGIN_SEGMENT_ADDR;
    case AGFX_METAL_AUTHOR_KIND_END_SEGMENT:
        return AGFX_METAL_END_SEGMENT_ADDR;
    case AGFX_METAL_AUTHOR_KIND_END_SEGMENT_STORE:
        return AGFX_METAL_END_SEGMENT_STORE_ADDR;
    case AGFX_METAL_AUTHOR_KIND_MTL_ADD:
        return AGFX_METAL_RESOURCE_LIST_ADD_ADDR;
    case AGFX_METAL_AUTHOR_KIND_FINALIZE:
        return AGFX_METAL_FINALIZE_SHMEM_HEADER_ADDR;
    case AGFX_METAL_AUTHOR_KIND_ALLOC_RESOURCE:
        return AGFX_METAL_ALLOC_RESOURCE_AT_INDEX_ADDR;
    case AGFX_METAL_AUTHOR_KIND_RESET:
        return AGFX_IOACCEL_RESOURCE_LIST_RESET_ADDR;
    case AGFX_METAL_AUTHOR_KIND_IOADD:
    case AGFX_METAL_AUTHOR_KIND_CUSTOM:
    default:
        return AGFX_IOACCEL_RESOURCE_LIST_ADD_ADDR;
    }
}

