static bool agfx_guest_sched_exec3_author_filter_match(
    uint32_t res_count, const bool res_valid[AGFX_EXEC3_AUTHOR_RES_MAX],
    const uint32_t res_id[AGFX_EXEC3_AUTHOR_RES_MAX])
{
    static const char *const id_env[AGFX_EXEC3_AUTHOR_RES_MAX] = {
        "QMU_DIAG_GUEST_SCHED_EXEC3_AUTHOR_MATCH_R0",
        "QMU_DIAG_GUEST_SCHED_EXEC3_AUTHOR_MATCH_R1",
        "QMU_DIAG_GUEST_SCHED_EXEC3_AUTHOR_MATCH_R2",
        "QMU_DIAG_GUEST_SCHED_EXEC3_AUTHOR_MATCH_R3",
        "QMU_DIAG_GUEST_SCHED_EXEC3_AUTHOR_MATCH_R4",
        "QMU_DIAG_GUEST_SCHED_EXEC3_AUTHOR_MATCH_R5",
        "QMU_DIAG_GUEST_SCHED_EXEC3_AUTHOR_MATCH_R6",
        "QMU_DIAG_GUEST_SCHED_EXEC3_AUTHOR_MATCH_R7",
    };
    uint64_t expected_count = agfx_env_u64(
        "QMU_DIAG_GUEST_SCHED_EXEC3_AUTHOR_MATCH_RES_COUNT", UINT64_MAX);

    if (expected_count != UINT64_MAX && res_count != expected_count) {
        return false;
    }
    for (unsigned i = 0; i < AGFX_EXEC3_AUTHOR_RES_MAX; i++) {
        uint64_t expected = agfx_env_u64(id_env[i], UINT64_MAX);

        if (expected != UINT64_MAX &&
            (!res_valid[i] || res_id[i] != expected)) {
            return false;
        }
    }
    return true;
}

