static bool agfx_guest_sched_guest_ptr_plausible(uint64_t ptr)
{
    return ptr >= 0xffffff0000000000ULL && ptr != UINT64_MAX;
}

static bool agfx_guest_sched_user_ptr_plausible(uint64_t ptr)
{
    return ptr >= 0x1000ULL && ptr < 0x0000800000000000ULL;
}

static bool agfx_guest_sched_data_ptr_plausible(uint64_t ptr)
{
    return agfx_guest_sched_guest_ptr_plausible(ptr) ||
           agfx_guest_sched_user_ptr_plausible(ptr);
}

static bool agfx_guest_sched_code_ptr_plausible(uint64_t ptr)
{
    return ptr >= 0xffffff7f00000000ULL && ptr < 0xffffff8100000000ULL;
}

static uint64_t agfx_read_le64(const uint8_t *p);

static uint32_t agfx_guest_sched_event_entry(const uint64_t *qwords,
                                             unsigned entry_index)
{
    unsigned qword_index = (entry_index + 1) / 2;

    if (((entry_index + 1) & 1) == 0) {
        return (uint32_t)(qwords[qword_index] & 0xffffffffu);
    }
    return (uint32_t)(qwords[qword_index] >> 32);
}

static uint32_t agfx_guest_sched_event_score(const uint64_t *qwords)
{
    uint32_t mask = (uint32_t)(qwords[0] & 0xffffffffu);
    uint32_t bit_count = 0;
    uint32_t score = 16;

    if (mask == 0 || (mask & ~0x7fffu) != 0) {
        return 0;
    }

    for (unsigned bit = 0; bit < 15; bit++) {
        uint32_t entry = agfx_guest_sched_event_entry(qwords, bit);
        uint32_t channel = entry & 0xffu;
        uint32_t stamp = entry >> 8;

        if ((mask & (1u << bit)) == 0) {
            continue;
        }

        bit_count++;
        if (entry == 0 || entry == UINT32_MAX || channel == 0xff ||
            channel > 0x20) {
            return 0;
        }
        score += 8;
        if (channel <= 8) {
            score += 4;
        }
        if (stamp != 0) {
            score += 2;
        }
    }

    if (bit_count == 0 || bit_count > 6) {
        return 0;
    }
    return score + bit_count;
}

static bool agfx_guest_sched_read_event_qwords(CPUState *cpu, uint64_t event_ptr,
                                               uint64_t *qwords)
{
    if (!agfx_guest_sched_guest_ptr_plausible(event_ptr) ||
        (event_ptr & 3u) != 0) {
        return false;
    }
    return cpu_memory_rw_debug(cpu, event_ptr, (uint8_t *)qwords,
                               AGFX_GUEST_SCHED_EVENT_QWORDS *
                                   sizeof(qwords[0]),
                               0) == 0;
}

static bool agfx_guest_sched_read_qwords(CPUState *cpu, uint64_t ptr,
                                         uint64_t *qwords, size_t count)
{
    if (!agfx_guest_sched_guest_ptr_plausible(ptr) || (ptr & 3u) != 0) {
        return false;
    }
    return cpu_memory_rw_debug(cpu, ptr, (uint8_t *)qwords,
                               count * sizeof(qwords[0]), 0) == 0;
}

