static void agfx_guest_sched_remove_iogpu_event_bps(CPUState *cpu,
                                                    uint64_t base)
{
    if (!cpu || !agfx_guest_sched_code_ptr_plausible(base)) {
        return;
    }

    agfx_guest_sched_remove_hw_breakpoint(
        cpu, base + AGFX_IOGPU_SET_EVENT_STAMP_NOWAIT_OFFSET);
    agfx_guest_sched_remove_hw_breakpoint(
        cpu, base + AGFX_IOGPU_SET_EVENT_STAMP_OFFSET);
    agfx_guest_sched_remove_hw_breakpoint(
        cpu, base + AGFX_IOGPU_SET_EVENT_STAMP_PAIR_OFFSET);
    agfx_guest_sched_remove_hw_breakpoint(
        cpu, base + AGFX_IOGPU_WRITE_EVENT_BARRIER_OFFSET);
    agfx_guest_sched_remove_hw_breakpoint(
        cpu, base + AGFX_IOGPU_MOVE_EVENT_OFFSET);
    agfx_guest_sched_remove_hw_breakpoint(
        cpu, base + AGFX_IOGPU_COPY_EVENT_OFFSET);
    agfx_guest_sched_remove_hw_breakpoint(
        cpu, base + AGFX_IOGPU_MERGE_EVENT_OFFSET);
    agfx_guest_sched_remove_hw_breakpoint(
        cpu, base + AGFX_IOGPU_TEST_EVENT_CONST_OFFSET);
    agfx_guest_sched_remove_hw_breakpoint(
        cpu, base + AGFX_IOGPU_TEST_EVENT_MUT_OFFSET);
    agfx_guest_sched_remove_hw_breakpoint(
        cpu, base + AGFX_IOGPU_TEST_EVENT_EXCLUDING_OFFSET);
    agfx_guest_sched_remove_hw_breakpoint(
        cpu, base + AGFX_IOGPU_TEST_EVENT_SUBMIT_OFFSET);
}

static void agfx_guest_sched_remove_apv_inner_bps(CPUState *cpu,
                                                  uint64_t base)
{
    if (!cpu || !agfx_guest_sched_code_ptr_plausible(base)) {
        return;
    }

    agfx_guest_sched_remove_hw_breakpoint(
        cpu, base + AGFX_APV_SUBMIT_TXN_GAMMA_MERGE_PRE_OFFSET);
    agfx_guest_sched_remove_hw_breakpoint(
        cpu, base + AGFX_APV_SUBMIT_TXN_GAMMA_MERGE_POST_OFFSET);
    agfx_guest_sched_remove_hw_breakpoint(
        cpu, base + AGFX_APV_SUBMIT_TXN_GAMMA_BARRIER_PRE_OFFSET);
    agfx_guest_sched_remove_hw_breakpoint(
        cpu, base + AGFX_APV_SUBMIT_TXN_GAMMA_BARRIER_POST_OFFSET);
}

static void agfx_guest_sched_remove_resource_life_bps(CPUState *cpu,
                                                      uint64_t apv_base,
                                                      uint64_t ioaccel_base)
{
    if (cpu && agfx_guest_sched_code_ptr_plausible(apv_base)) {
        agfx_guest_sched_remove_hw_breakpoint(
            cpu, apv_base + AGFX_APV_RESOURCE_REMOVE_FROM_CHANNEL_OFFSET);
    }
    if (cpu && agfx_guest_sched_code_ptr_plausible(ioaccel_base)) {
        agfx_guest_sched_remove_hw_breakpoint(
            cpu, ioaccel_base +
                     AGFX_IOACCEL_RESOURCE_REMOVE_FROM_CHANNEL_OFFSET);
        agfx_guest_sched_remove_hw_breakpoint(
            cpu, ioaccel_base + AGFX_IOACCEL_RESOURCE_ADD_TO_CHANNEL_OFFSET);
    }
}

static void agfx_guest_sched_remove_resource_state_wps(CPUState *cpu,
                                                       uint64_t state_addr,
                                                       uint64_t ref_addr,
                                                       uint64_t dirty_addr)
{
    if (!cpu) {
        return;
    }
    if (agfx_guest_sched_guest_ptr_plausible(state_addr)) {
        agfx_guest_sched_remove_hw_watchpoint(cpu, state_addr,
                                              sizeof(uint64_t));
    }
    if (agfx_guest_sched_guest_ptr_plausible(ref_addr)) {
        agfx_guest_sched_remove_hw_watchpoint(cpu, ref_addr,
                                              sizeof(uint32_t));
    }
    if (agfx_guest_sched_guest_ptr_plausible(dirty_addr)) {
        agfx_guest_sched_remove_hw_watchpoint(cpu, dirty_addr,
                                              sizeof(uint8_t));
    }
}

static const char *agfx_guest_sched_iogpu_event_func_name(uint64_t offset)
{
    switch (offset) {
    case AGFX_IOGPU_SET_EVENT_STAMP_NOWAIT_OFFSET:
        return "IOGPUEventMachine::setEventStampNoWait";
    case AGFX_IOGPU_SET_EVENT_STAMP_OFFSET:
        return "IOGPUEventMachine::setEventStamp";
    case AGFX_IOGPU_SET_EVENT_STAMP_PAIR_OFFSET:
        return "IOGPUEventMachine::setEventStampPair";
    case AGFX_IOGPU_WRITE_EVENT_BARRIER_OFFSET:
        return "IOGPUEventMachine::writeEventBarrierCommand";
    case AGFX_IOGPU_MOVE_EVENT_OFFSET:
        return "IOGPUEventMachine::moveEvent";
    case AGFX_IOGPU_COPY_EVENT_OFFSET:
        return "IOGPUEventMachine::copyEvent";
    case AGFX_IOGPU_MERGE_EVENT_OFFSET:
        return "IOGPUEventMachine::mergeEvent";
    case AGFX_IOGPU_TEST_EVENT_CONST_OFFSET:
        return "IOGPUEventMachine::testEvent_const";
    case AGFX_IOGPU_TEST_EVENT_MUT_OFFSET:
        return "IOGPUEventMachine::testEvent_mut";
    case AGFX_IOGPU_TEST_EVENT_EXCLUDING_OFFSET:
        return "IOGPUEventMachine::testEventExcluding";
    case AGFX_IOGPU_TEST_EVENT_SUBMIT_OFFSET:
        return "IOGPUEventMachine::testEventAgainstSubmitStampsUnlocked";
    default:
        return "unknown";
    }
}

static bool agfx_guest_sched_iogpu_event_offset_is_test(uint64_t offset)
{
    switch (offset) {
    case AGFX_IOGPU_TEST_EVENT_CONST_OFFSET:
    case AGFX_IOGPU_TEST_EVENT_MUT_OFFSET:
    case AGFX_IOGPU_TEST_EVENT_EXCLUDING_OFFSET:
    case AGFX_IOGPU_TEST_EVENT_SUBMIT_OFFSET:
        return true;
    default:
        return false;
    }
}

static const char *agfx_guest_sched_resource_life_func_name(uint64_t pc,
                                                            uint64_t apv_base,
                                                            uint64_t ioaccel_base)
{
    if (agfx_guest_sched_code_ptr_plausible(apv_base) &&
        pc == apv_base + AGFX_APV_RESOURCE_REMOVE_FROM_CHANNEL_OFFSET) {
        return "AppleParavirtResource::removeFromChannel";
    }
    if (agfx_guest_sched_code_ptr_plausible(ioaccel_base) &&
        pc == ioaccel_base +
                  AGFX_IOACCEL_RESOURCE_REMOVE_FROM_CHANNEL_OFFSET) {
        return "IOAccelResource2::removeFromChannel";
    }
    if (agfx_guest_sched_code_ptr_plausible(ioaccel_base) &&
        pc == ioaccel_base + AGFX_IOACCEL_RESOURCE_ADD_TO_CHANNEL_OFFSET) {
        return "IOAccelResource2::addToChannel";
    }
    return "unknown";
}

static bool agfx_guest_sched_resource_life_pc(uint64_t pc, uint64_t apv_base,
                                              uint64_t ioaccel_base)
{
    return strcmp(agfx_guest_sched_resource_life_func_name(
                      pc, apv_base, ioaccel_base),
                  "unknown") != 0;
}

