static bool agfx_guest_sched_exec3_scissor_command_valid(
    const uint8_t command[40], uint64_t *header, uint64_t *x, uint64_t *y,
    uint64_t *width, uint64_t *height)
{
    uint64_t local_header = agfx_read_le64(command);
    uint64_t local_x = agfx_read_le64(command + 8);
    uint64_t local_y = agfx_read_le64(command + 16);
    uint64_t local_width = agfx_read_le64(command + 24);
    uint64_t local_height = agfx_read_le64(command + 32);

    if (header) {
        *header = local_header;
    }
    if (x) {
        *x = local_x;
    }
    if (y) {
        *y = local_y;
    }
    if (width) {
        *width = local_width;
    }
    if (height) {
        *height = local_height;
    }

    return (uint32_t)local_header == 0x75 &&
           (uint32_t)(local_header >> 32) == sizeof(uint64_t) * 5 &&
           local_x <= 0x10000 && local_y <= 0x10000 &&
           local_width != 0 && local_width <= 0x10000 &&
           local_height != 0 && local_height <= 0x10000;
}

static bool agfx_guest_sched_exec3_scissor_target_valid(
    uint64_t x, uint64_t y, uint64_t width, uint64_t height)
{
    return x == 880 && width == 160 && height <= 64 &&
           y <= UINT64_MAX - height && y + height == 995;
}

static void agfx_guest_sched_log_exec3_writer_frame_deep(
    AppleGfxMLState *s, CPUState *cpu, uint64_t target_seq,
    uint64_t y, uint64_t height,
    const uint64_t frame_fp[AGFX_GUEST_SCHED_FRAME_DEPTH],
    const uint64_t frame_ret[AGFX_GUEST_SCHED_FRAME_DEPTH])
{
    if (!s || !cpu || agfx_env_u64(
            "QMU_DIAG_GUEST_SCHED_EXEC3_AUTHOR_WRITER_FRAME_DEEP", 0) == 0) {
        return;
    }

    for (unsigned frame = 0; frame < 12; frame++) {
        uint8_t bytes[0x200] = { 0 };
        uint64_t base = frame_fp[frame] >= 0x100 ?
            frame_fp[frame] - 0x100 : 0;
        bool valid = base != 0 &&
            agfx_guest_sched_user_ptr_plausible(base) &&
            cpu_memory_rw_debug(cpu, base, bytes, sizeof(bytes), 0) == 0;
        uint64_t hash = valid ? agfx_fnv1a64(bytes, sizeof(bytes)) : 0;

        for (unsigned chunk = 0; chunk < 4; chunk++) {
            const uint8_t *p = bytes + chunk * 0x80;

            agfx_log(s,
                     "[apple-gfx-ml] DIAG_GUEST_SCHED_EXEC3_WRITER_FRAME_DEEP "
                     "target_seq=%llu y=%llu height=%llu frame=%u "
                     "fp=0x%llx ret=0x%llx base=0x%llx valid=%d "
                     "hash=0x%llx chunk=%u chunk_off=0x%x "
                     "q0=0x%llx q1=0x%llx q2=0x%llx q3=0x%llx "
                     "q4=0x%llx q5=0x%llx q6=0x%llx q7=0x%llx "
                     "q8=0x%llx q9=0x%llx q10=0x%llx q11=0x%llx "
                     "q12=0x%llx q13=0x%llx q14=0x%llx q15=0x%llx\n",
                     (unsigned long long)target_seq,
                     (unsigned long long)y,
                     (unsigned long long)height,
                     frame,
                     (unsigned long long)frame_fp[frame],
                     (unsigned long long)frame_ret[frame],
                     (unsigned long long)base,
                     valid,
                     (unsigned long long)hash,
                     chunk,
                     chunk * 0x80,
                     (unsigned long long)agfx_read_le64(p),
                     (unsigned long long)agfx_read_le64(p + 8),
                     (unsigned long long)agfx_read_le64(p + 16),
                     (unsigned long long)agfx_read_le64(p + 24),
                     (unsigned long long)agfx_read_le64(p + 32),
                     (unsigned long long)agfx_read_le64(p + 40),
                     (unsigned long long)agfx_read_le64(p + 48),
                     (unsigned long long)agfx_read_le64(p + 56),
                     (unsigned long long)agfx_read_le64(p + 64),
                     (unsigned long long)agfx_read_le64(p + 72),
                     (unsigned long long)agfx_read_le64(p + 80),
                     (unsigned long long)agfx_read_le64(p + 88),
                     (unsigned long long)agfx_read_le64(p + 96),
                     (unsigned long long)agfx_read_le64(p + 104),
                     (unsigned long long)agfx_read_le64(p + 112),
                     (unsigned long long)agfx_read_le64(p + 120));
        }
    }
}

static bool agfx_guest_sched_log_quartz_object(
    AppleGfxMLState *s, CPUState *cpu, uint64_t hit_seq, uint64_t ch5,
    const char *role, uint64_t ptr, uint64_t qword[64])
{
    uint8_t bytes[0x200] = { 0 };

    if (!s || !cpu || !role || !qword ||
        !agfx_guest_sched_user_ptr_plausible(ptr) ||
        cpu_memory_rw_debug(cpu, ptr, bytes, sizeof(bytes), 0) != 0) {
        return false;
    }
    for (unsigned i = 0; i < 64; i++) {
        qword[i] = agfx_read_le64(bytes + i * sizeof(qword[i]));
    }
    for (unsigned chunk = 0; chunk < 4; chunk++) {
        const uint64_t *q = qword + chunk * 16;

        agfx_log(s,
                 "[apple-gfx-ml] DIAG_GUEST_SCHED_QUARTZ_OBJECT "
                 "hit_seq=%llu ch5=%llu role=%s ptr=0x%llx "
                 "hash=0x%llx chunk=%u chunk_off=0x%x "
                 "q0=0x%llx q1=0x%llx q2=0x%llx q3=0x%llx "
                 "q4=0x%llx q5=0x%llx q6=0x%llx q7=0x%llx "
                 "q8=0x%llx q9=0x%llx q10=0x%llx q11=0x%llx "
                 "q12=0x%llx q13=0x%llx q14=0x%llx q15=0x%llx\n",
                 (unsigned long long)hit_seq,
                 (unsigned long long)ch5,
                 role,
                 (unsigned long long)ptr,
                 (unsigned long long)agfx_fnv1a64(bytes, sizeof(bytes)),
                 chunk,
                 chunk * 0x80,
                 (unsigned long long)q[0],
                 (unsigned long long)q[1],
                 (unsigned long long)q[2],
                 (unsigned long long)q[3],
                 (unsigned long long)q[4],
                 (unsigned long long)q[5],
                 (unsigned long long)q[6],
                 (unsigned long long)q[7],
                 (unsigned long long)q[8],
                 (unsigned long long)q[9],
                 (unsigned long long)q[10],
                 (unsigned long long)q[11],
                 (unsigned long long)q[12],
                 (unsigned long long)q[13],
                 (unsigned long long)q[14],
                 (unsigned long long)q[15]);
    }
    return true;
}

static void agfx_guest_sched_log_quartz_layer_state(
    AppleGfxMLState *s, CPUState *cpu, uint64_t hit_seq, uint64_t ch5,
    const uint64_t frame_fp[AGFX_GUEST_SCHED_FRAME_DEPTH])
{
    static const char *const object_role[2] = {
        "render_background_renderer", "render_background_layer",
    };
    static const char *const nested_role[2][5] = {
        {
            "render_background_renderer_q0",
            "render_background_renderer_q1",
            "render_background_renderer_q2",
            "render_background_renderer_q3",
            "render_background_renderer_q17",
        },
        {
            "render_background_layer_q0",
            "render_background_layer_q1",
            "render_background_layer_q2",
            "render_background_layer_q3",
            "render_background_layer_q17",
        },
    };
    static const unsigned nested_qword[5] = { 0, 1, 2, 3, 17 };
    uint64_t min_ch5 = agfx_env_u64(
        "QMU_DIAG_GUEST_SCHED_EXEC3_AUTHOR_QUARTZ_STATE_MIN_CH5", 0);
    uint64_t max_ch5 = agfx_env_u64(
        "QMU_DIAG_GUEST_SCHED_EXEC3_AUTHOR_QUARTZ_STATE_MAX_CH5",
        UINT64_MAX);
    uint64_t closure[3] = { 0 };
    uint64_t object[2] = { 0 };

    if (!s || !cpu || agfx_env_u64(
            "QMU_DIAG_GUEST_SCHED_EXEC3_AUTHOR_QUARTZ_STATE", 0) == 0 ||
        ch5 < min_ch5 || ch5 > max_ch5 ||
        !agfx_guest_sched_user_ptr_plausible(frame_fp[11]) ||
        cpu_memory_rw_debug(cpu, frame_fp[11] - 0x50,
                            (uint8_t *)closure, sizeof(closure), 0) != 0) {
        return;
    }
    object[0] = closure[1];
    object[1] = closure[2];

    agfx_log(s,
             "[apple-gfx-ml] DIAG_GUEST_SCHED_QUARTZ_STATE "
             "hit_seq=%llu ch5=%llu frame11_fp=0x%llx "
             "closure_vtable=0x%llx renderer=0x%llx layer=0x%llx\n",
             (unsigned long long)hit_seq,
             (unsigned long long)ch5,
             (unsigned long long)frame_fp[11],
             (unsigned long long)closure[0],
             (unsigned long long)object[0],
             (unsigned long long)object[1]);
    for (unsigned i = 0; i < ARRAY_SIZE(object); i++) {
        uint64_t qword[64] = { 0 };

        if (!agfx_guest_sched_log_quartz_object(
                s, cpu, hit_seq, ch5, object_role[i], object[i], qword)) {
            continue;
        }
        for (unsigned nested_i = 0;
             nested_i < ARRAY_SIZE(nested_qword); nested_i++) {
            uint64_t nested[64] = { 0 };
            unsigned qword_i = nested_qword[nested_i];

            (void)agfx_guest_sched_log_quartz_object(
                s, cpu, hit_seq, ch5, nested_role[i][nested_i],
                qword[qword_i], nested);
        }
    }
}

static uint64_t agfx_guest_sched_quartz_contents_min_ch5(void)
{
    return agfx_env_u64(
        "QMU_DIAG_GUEST_SCHED_EXEC3_AUTHOR_QUARTZ_CONTENTS_MIN_CH5",
        agfx_env_u64(
            "QMU_DIAG_GUEST_SCHED_EXEC3_AUTHOR_QUARTZ_STATE_MIN_CH5", 0));
}

static uint64_t agfx_guest_sched_quartz_contents_max_ch5(void)
{
    return agfx_env_u64(
        "QMU_DIAG_GUEST_SCHED_EXEC3_AUTHOR_QUARTZ_CONTENTS_MAX_CH5",
        agfx_env_u64(
            "QMU_DIAG_GUEST_SCHED_EXEC3_AUTHOR_QUARTZ_STATE_MAX_CH5",
            UINT64_MAX));
}

static uint64_t agfx_guest_sched_quartz_contents_max_hits(void)
{
    return agfx_env_u64(
        "QMU_DIAG_GUEST_SCHED_EXEC3_AUTHOR_QUARTZ_CONTENTS_MAX_HITS", 128);
}

static bool agfx_guest_sched_quartz_background_mode(void)
{
    const char *mode = getenv(
        "QMU_DIAG_GUEST_SCHED_EXEC3_AUTHOR_QUARTZ_CONTENTS_BP_MODE");

    return mode && strcmp(mode, "background") == 0;
}

static uint64_t agfx_guest_sched_find_quartz_contents_entry(
    CPUState *cpu, uint64_t render_background_ret)
{
    static const uint8_t contents_signature[] = {
        0x55, 0x48, 0x89, 0xe5, 0x41, 0x57, 0x41, 0x56,
        0x41, 0x55, 0x41, 0x54, 0x53, 0x48, 0x81, 0xec,
        0x78, 0x03, 0x00, 0x00, 0x49, 0x89, 0xf9,
    };
    static const uint8_t background_signature[] = {
        0x55, 0x48, 0x89, 0xe5, 0x41, 0x57, 0x41, 0x56,
        0x41, 0x55, 0x41, 0x54, 0x53, 0x48, 0x83, 0xec,
        0x78, 0x48, 0x89, 0xf3, 0x49, 0x89, 0xfe,
    };
    const uint64_t radius = 0x1000;
    const size_t scan_size = radius * 2;
    const uint8_t *signature = agfx_guest_sched_quartz_background_mode() ?
        background_signature : contents_signature;
    const size_t signature_size = sizeof(contents_signature);
    uint64_t static_entry = agfx_guest_sched_quartz_background_mode() ?
        AGFX_QUARTZ_RENDER_BACKGROUND_ENTRY_STATIC :
        AGFX_QUARTZ_RENDER_CONTENTS_ENTRY_STATIC;
    uint64_t approximate;
    uint64_t scan_base;
    uint8_t *bytes;
    uint64_t result = 0;

    if (!cpu || render_background_ret <=
            AGFX_QUARTZ_RENDER_BACKGROUND_RET_STATIC) {
        return 0;
    }
    approximate = static_entry +
        (render_background_ret - AGFX_QUARTZ_RENDER_BACKGROUND_RET_STATIC);
    scan_base = approximate > radius ? approximate - radius : 0;
    bytes = g_malloc(scan_size);
    if (cpu_memory_rw_debug(cpu, scan_base, bytes, scan_size, 0) == 0) {
        for (size_t off = 0; off + signature_size <= scan_size; off++) {
            if (memcmp(bytes + off, signature, signature_size) == 0) {
                result = scan_base + off;
                break;
            }
        }
    }
    g_free(bytes);
    return result;
}

static void agfx_guest_sched_maybe_arm_quartz_contents_bp(
    AppleGfxMLState *s, CPUState *cpu, uint64_t source_hit,
    const uint64_t frame_fp[AGFX_GUEST_SCHED_FRAME_DEPTH],
    const uint64_t frame_ret[AGFX_GUEST_SCHED_FRAME_DEPTH])
{
    uint64_t closure[3] = { 0 };
    uint64_t entry;
    uint64_t ch5;
    int rc;

    if (!s || !cpu || !agfx_guest_sched_quartz_contents_bp_on() ||
        qatomic_read(&s->guest_sched_quartz_contents_bp_target_layer) != 0 ||
        !agfx_guest_sched_user_ptr_plausible(frame_fp[11]) ||
        !agfx_guest_sched_user_ptr_plausible(frame_ret[10]) ||
        cpu_memory_rw_debug(cpu, frame_fp[11] - 0x50,
                            (uint8_t *)closure, sizeof(closure), 0) != 0 ||
        !agfx_guest_sched_user_ptr_plausible(closure[1]) ||
        !agfx_guest_sched_user_ptr_plausible(closure[2])) {
        return;
    }
    ch5 = qatomic_read(&s->guest_sched_ch5_interval_id);
    if (ch5 < agfx_guest_sched_quartz_contents_min_ch5() ||
        ch5 > agfx_guest_sched_quartz_contents_max_ch5()) {
        return;
    }
    entry = agfx_guest_sched_find_quartz_contents_entry(cpu, frame_ret[10]);
    if (!agfx_guest_sched_user_ptr_plausible(entry) ||
        qatomic_cmpxchg(&s->guest_sched_quartz_contents_bp_armed,
                        0, 1) != 0) {
        agfx_log(s,
                 "[apple-gfx-ml] DIAG_GUEST_SCHED_QUARTZ_CONTENTS_BP_ARM "
                 "source_hit=%llu state=scan_failed ch5=%llu "
                 "mode=%s "
                 "frame10_ret=0x%llx renderer=0x%llx layer=0x%llx "
                 "entry=0x%llx\n",
                 (unsigned long long)source_hit,
                 (unsigned long long)ch5,
                 agfx_guest_sched_quartz_background_mode() ?
                     "background" : "contents",
                 (unsigned long long)frame_ret[10],
                 (unsigned long long)closure[1],
                 (unsigned long long)closure[2],
                 (unsigned long long)entry);
        return;
    }

    qatomic_set(&s->guest_sched_quartz_contents_bp_addr, entry);
    qatomic_set(&s->guest_sched_quartz_contents_bp_target_renderer,
                closure[1]);
    qatomic_set(&s->guest_sched_quartz_contents_bp_target_layer, closure[2]);
    rc = agfx_guest_sched_insert_hw_breakpoint_all(entry);
    if (rc != 0) {
        qatomic_set(&s->guest_sched_quartz_contents_bp_armed, 0);
        qatomic_set(&s->guest_sched_quartz_contents_bp_target_renderer, 0);
        qatomic_set(&s->guest_sched_quartz_contents_bp_target_layer, 0);
    }
    agfx_log(s,
             "[apple-gfx-ml] DIAG_GUEST_SCHED_QUARTZ_CONTENTS_BP_ARM "
             "source_hit=%llu state=%s rc=%d ch5=%llu "
             "mode=%s "
             "frame10_ret=0x%llx renderer=0x%llx layer=0x%llx "
             "entry=0x%llx\n",
             (unsigned long long)source_hit,
             rc == 0 ? "armed" : "failed",
             rc,
             (unsigned long long)ch5,
             agfx_guest_sched_quartz_background_mode() ?
                 "background" : "contents",
             (unsigned long long)frame_ret[10],
             (unsigned long long)closure[1],
             (unsigned long long)closure[2],
             (unsigned long long)entry);
}

static bool agfx_guest_sched_handle_quartz_contents_rearm_bp(
    AppleGfxMLState *s, CPUState *cpu)
{
    uint64_t pc;
    uint64_t return_addr;
    uint64_t entry;
    uint64_t ch5;
    uint64_t hits;
    int remove_rc;
    int insert_rc = -1;

    if (!s || !cpu || !agfx_guest_sched_quartz_contents_bp_on() ||
        qatomic_read(&s->guest_sched_quartz_contents_rearm_bp_armed) == 0 ||
        !cpu->cc || !cpu->cc->get_pc) {
        return false;
    }
    cpu_synchronize_state(cpu);
    pc = cpu->cc->get_pc(cpu);
    return_addr = qatomic_read(
        &s->guest_sched_quartz_contents_rearm_bp_addr);
    if (pc != return_addr) {
        return false;
    }
    remove_rc = agfx_guest_sched_remove_hw_breakpoint_all(return_addr);
    qatomic_set(&s->guest_sched_quartz_contents_rearm_bp_armed, 0);

    ch5 = qatomic_read(&s->guest_sched_ch5_interval_id);
    hits = qatomic_read(&s->guest_sched_quartz_contents_bp_hit_seq);
    entry = qatomic_read(&s->guest_sched_quartz_contents_bp_addr);
    if (ch5 <= agfx_guest_sched_quartz_contents_max_ch5() &&
        hits < agfx_guest_sched_quartz_contents_max_hits() &&
        agfx_guest_sched_user_ptr_plausible(entry) &&
        qatomic_cmpxchg(&s->guest_sched_quartz_contents_bp_armed,
                        0, 1) == 0) {
        insert_rc = agfx_guest_sched_insert_hw_breakpoint_all(entry);
        if (insert_rc != 0) {
            qatomic_set(&s->guest_sched_quartz_contents_bp_armed, 0);
        }
    }
    agfx_log(s,
             "[apple-gfx-ml] DIAG_GUEST_SCHED_QUARTZ_CONTENTS_REARM "
             "pc=0x%llx ch5=%llu hits=%llu remove_rc=%d "
             "entry=0x%llx insert_rc=%d armed=%d\n",
             (unsigned long long)pc,
             (unsigned long long)ch5,
             (unsigned long long)hits,
             remove_rc,
             (unsigned long long)entry,
             insert_rc,
             qatomic_read(&s->guest_sched_quartz_contents_bp_armed));
    return true;
}

static bool agfx_guest_sched_handle_quartz_contents_bp(
    AppleGfxMLState *s, CPUState *cpu)
{
    uint64_t regs[AGFX_X86_REG_COUNT] = { 0 };
    uint64_t renderer_qword[64] = { 0 };
    uint64_t layer_qword[64] = { 0 };
    uint64_t nested[64] = { 0 };
    uint64_t pc;
    uint64_t entry;
    uint64_t return_addr = 0;
    uint64_t hit_seq;
    uint64_t ch5;
    uint64_t renderer;
    uint64_t layer;
    uint64_t target_layer;
    uint8_t *env;
    bool target_match;
    int remove_rc;
    int rearm_rc = -1;

    if (!s || !cpu || !agfx_guest_sched_quartz_contents_bp_on() ||
        qatomic_read(&s->guest_sched_quartz_contents_bp_armed) == 0 ||
        !cpu->cc || !cpu->cc->get_pc) {
        return false;
    }
    cpu_synchronize_state(cpu);
    pc = cpu->cc->get_pc(cpu);
    entry = qatomic_read(&s->guest_sched_quartz_contents_bp_addr);
    if (pc != entry) {
        return false;
    }
    remove_rc = agfx_guest_sched_remove_hw_breakpoint_all(entry);
    qatomic_set(&s->guest_sched_quartz_contents_bp_armed, 0);

    env = (uint8_t *)cpu_env(cpu);
    for (unsigned i = 0; i < AGFX_X86_REG_COUNT; i++) {
        memcpy(&regs[i], env + i * sizeof(uint64_t), sizeof(regs[i]));
    }
    if (agfx_guest_sched_user_ptr_plausible(
            regs[AGFX_X86_REG_RSP_INDEX])) {
        (void)cpu_memory_rw_debug(cpu, regs[AGFX_X86_REG_RSP_INDEX],
                                  (uint8_t *)&return_addr,
                                  sizeof(return_addr), 0);
    }
    renderer = regs[AGFX_X86_REG_RDI_INDEX];
    layer = regs[AGFX_X86_REG_RSI_INDEX];
    target_layer = qatomic_read(
        &s->guest_sched_quartz_contents_bp_target_layer);
    target_match = layer == target_layer;
    ch5 = qatomic_read(&s->guest_sched_ch5_interval_id);
    hit_seq = qatomic_fetch_inc(
        &s->guest_sched_quartz_contents_bp_hit_seq) + 1;

    agfx_log(s,
             "[apple-gfx-ml] DIAG_GUEST_SCHED_QUARTZ_CONTENTS_ENTRY "
             "hit_seq=%llu ch5=%llu pc=0x%llx return=0x%llx "
             "mode=%s "
             "renderer=0x%llx layer=0x%llx target_layer=0x%llx "
             "target_match=%d target_renderer=0x%llx "
             "last_kick1=%llu last_kick2=%llu last_kick5=%llu\n",
             (unsigned long long)hit_seq,
             (unsigned long long)ch5,
             (unsigned long long)pc,
             (unsigned long long)return_addr,
             agfx_guest_sched_quartz_background_mode() ?
                 "background" : "contents",
             (unsigned long long)renderer,
             (unsigned long long)layer,
             (unsigned long long)target_layer,
             target_match,
             (unsigned long long)qatomic_read(
                 &s->guest_sched_quartz_contents_bp_target_renderer),
             (unsigned long long)qatomic_read(&s->guest_sched_last_kick1_seq),
             (unsigned long long)qatomic_read(&s->guest_sched_last_kick2_seq),
             (unsigned long long)qatomic_read(&s->guest_sched_last_kick5_seq));

    if (target_match && agfx_guest_sched_log_quartz_object(
            s, cpu, hit_seq, ch5, "quartz_contents_renderer",
            renderer, renderer_qword)) {
        (void)agfx_guest_sched_log_quartz_object(
            s, cpu, hit_seq, ch5, "quartz_contents_context",
            renderer_qword[0], nested);
    }
    if (target_match && agfx_guest_sched_log_quartz_object(
            s, cpu, hit_seq, ch5, "quartz_contents_layer",
            layer, layer_qword)) {
        (void)agfx_guest_sched_log_quartz_object(
            s, cpu, hit_seq, ch5, "quartz_contents_layer_q3",
            layer_qword[3], nested);
    }

    if (agfx_guest_sched_user_ptr_plausible(return_addr) &&
        ch5 <= agfx_guest_sched_quartz_contents_max_ch5() &&
        hit_seq < agfx_guest_sched_quartz_contents_max_hits() &&
        qatomic_cmpxchg(&s->guest_sched_quartz_contents_rearm_bp_armed,
                        0, 1) == 0) {
        qatomic_set(&s->guest_sched_quartz_contents_rearm_bp_addr,
                    return_addr);
        rearm_rc = agfx_guest_sched_insert_hw_breakpoint_all(return_addr);
        if (rearm_rc != 0) {
            qatomic_set(&s->guest_sched_quartz_contents_rearm_bp_armed, 0);
        }
    }
    agfx_log(s,
             "[apple-gfx-ml] DIAG_GUEST_SCHED_QUARTZ_CONTENTS_RETURN_ARM "
             "hit_seq=%llu return=0x%llx remove_rc=%d rearm_rc=%d "
             "armed=%d\n",
             (unsigned long long)hit_seq,
             (unsigned long long)return_addr,
             remove_rc,
             rearm_rc,
             qatomic_read(&s->guest_sched_quartz_contents_rearm_bp_armed));
    return true;
}

static void agfx_guest_sched_rearm_exec3_writer_target(
    AppleGfxMLState *s, CPUState *cpu, const char *source,
    uint64_t source_seq)
{
    uint64_t bp_addr;
    uint64_t arm_seq;
    uint64_t max_hits;
    bool sampled;
    int rc;

    if (!s || !cpu || !agfx_guest_sched_exec3_writer_bp_on() ||
        qatomic_read(&s->guest_sched_exec3_writer_bp_discovered) == 0 ||
        qatomic_read(&s->guest_sched_exec3_writer_rearm_bp_armed) != 0) {
        return;
    }

    max_hits = agfx_guest_sched_exec3_writer_bp_max_hits();
    if (max_hits != 0 &&
        qatomic_read(&s->guest_sched_exec3_writer_bp_hit_seq) >= max_hits) {
        return;
    }
    bp_addr = qatomic_read(&s->guest_sched_exec3_writer_bp_addr);
    if (!agfx_guest_sched_user_ptr_plausible(bp_addr) ||
        qatomic_cmpxchg(&s->guest_sched_exec3_writer_bp_armed, 0, 1) != 0) {
        return;
    }

    arm_seq = qatomic_fetch_inc(
        &s->guest_sched_exec3_writer_bp_arm_seq) + 1;
    rc = agfx_guest_sched_insert_hw_breakpoint_all(bp_addr);
    if (rc != 0) {
        qatomic_set(&s->guest_sched_exec3_writer_bp_armed, 0);
    }
    sampled = source_seq <= 4 || source_seq % 256 == 0 || rc != 0;
    if (sampled) {
        agfx_log(s,
                 "[apple-gfx-ml] DIAG_GUEST_SCHED_EXEC3_WRITER_BP_ARM "
                 "source=%s source_seq=%llu state=%s arm_seq=%llu "
                 "bp=0x%llx rc=%d ch5=%llu hit_seq=%llu target_seq=%llu\n",
                 source ? source : "unknown",
                 (unsigned long long)source_seq,
                 rc == 0 ? "armed" : "failed",
                 (unsigned long long)arm_seq,
                 (unsigned long long)bp_addr,
                 rc,
                 (unsigned long long)qatomic_read(
                     &s->guest_sched_ch5_interval_id),
                 (unsigned long long)qatomic_read(
                     &s->guest_sched_exec3_writer_bp_hit_seq),
                 (unsigned long long)qatomic_read(
                     &s->guest_sched_exec3_writer_bp_target_seq));
    }
}

static void agfx_guest_sched_arm_exec3_writer_rearm_bp(
    AppleGfxMLState *s, CPUState *cpu, uint64_t return_addr,
    const char *source, uint64_t source_seq)
{
    uint64_t arm_seq;
    uint64_t max_hits;
    bool sampled;
    int rc;

    if (!s || !cpu || !agfx_guest_sched_exec3_writer_bp_on() ||
        !agfx_guest_sched_user_ptr_plausible(return_addr) ||
        qatomic_read(&s->guest_sched_exec3_writer_bp_armed) != 0) {
        return;
    }
    max_hits = agfx_guest_sched_exec3_writer_bp_max_hits();
    if (max_hits != 0 &&
        qatomic_read(&s->guest_sched_exec3_writer_bp_hit_seq) >= max_hits) {
        return;
    }
    if (qatomic_cmpxchg(&s->guest_sched_exec3_writer_rearm_bp_armed,
                        0, 1) != 0) {
        return;
    }

    arm_seq = qatomic_fetch_inc(
        &s->guest_sched_exec3_writer_rearm_bp_arm_seq) + 1;
    qatomic_set(&s->guest_sched_exec3_writer_rearm_bp_addr, return_addr);
    rc = agfx_guest_sched_insert_hw_breakpoint_all(return_addr);
    if (rc != 0) {
        qatomic_set(&s->guest_sched_exec3_writer_rearm_bp_armed, 0);
    }
    sampled = source_seq <= 4 || source_seq % 256 == 0 || rc != 0;
    if (sampled) {
        agfx_log(s,
                 "[apple-gfx-ml] DIAG_GUEST_SCHED_EXEC3_WRITER_REARM_ARM "
                 "source=%s source_seq=%llu state=%s arm_seq=%llu "
                 "return_bp=0x%llx rc=%d ch5=%llu\n",
                 source ? source : "unknown",
                 (unsigned long long)source_seq,
                 rc == 0 ? "armed" : "failed",
                 (unsigned long long)arm_seq,
                 (unsigned long long)return_addr,
                 rc,
                 (unsigned long long)qatomic_read(
                     &s->guest_sched_ch5_interval_id));
    }
}

static void agfx_guest_sched_discover_exec3_writer_bp(
    AppleGfxMLState *s, CPUState *cpu, uint64_t writer_pc,
    uint64_t return_addr, uint64_t wp_hit_seq, uint64_t current_cr3)
{
    if (!s || !cpu || !agfx_guest_sched_exec3_writer_bp_on() ||
        !agfx_guest_sched_user_ptr_plausible(writer_pc) ||
        qatomic_cmpxchg(&s->guest_sched_exec3_writer_bp_discovered,
                        0, 1) != 0) {
        return;
    }

    qatomic_set(&s->guest_sched_exec3_writer_bp_addr, writer_pc);
    qatomic_set(&s->guest_sched_exec3_writer_bp_discovery_wp_hit, wp_hit_seq);
    qatomic_set(&s->guest_sched_exec3_writer_bp_discovery_cr3, current_cr3);
    agfx_log(s,
             "[apple-gfx-ml] DIAG_GUEST_SCHED_EXEC3_WRITER_BP_DISCOVER "
             "wp_hit_seq=%llu writer_pc=0x%llx return_bp=0x%llx "
             "return_valid=%d cr3=0x%llx ch5=%llu\n",
             (unsigned long long)wp_hit_seq,
             (unsigned long long)writer_pc,
             (unsigned long long)return_addr,
             agfx_guest_sched_user_ptr_plausible(return_addr),
             (unsigned long long)current_cr3,
             (unsigned long long)qatomic_read(
                 &s->guest_sched_ch5_interval_id));
    agfx_guest_sched_arm_exec3_writer_rearm_bp(
        s, cpu, return_addr, "discover", wp_hit_seq);
}

