static bool agfx_guest_sched_metal_author_pc_plausible(uint64_t ptr)
{
    return agfx_guest_sched_user_ptr_plausible(ptr) ||
           agfx_guest_sched_code_ptr_plausible(ptr);
}

static bool agfx_guest_sched_metal_author_signature_for_kind(
    uint32_t kind, const uint8_t **sig, size_t *sig_len)
{
    static const uint8_t begin_segment_sig[] = {
        0x55, 0x48, 0x89, 0xe5, 0x41, 0x57, 0x41, 0x56,
        0x53, 0x50, 0x49, 0x89, 0xf6, 0x48, 0x89, 0xfb,
        0x4c, 0x8b, 0x7f, 0x28, 0x48, 0x83, 0x7f, 0x58,
    };
    static const uint8_t alloc_resource_sig[] = {
        0x55, 0x48, 0x89, 0xe5, 0x41, 0x57, 0x41, 0x56,
        0x41, 0x55, 0x41, 0x54, 0x53, 0x50, 0x49, 0x89,
        0xfe, 0x4c, 0x8b, 0xbf, 0xe0, 0x02, 0x00, 0x00,
    };
    static const uint8_t mtl_add_sig[] = {
        0x55, 0x48, 0x89, 0xe5, 0x41, 0x56, 0x53, 0x48,
        0x89, 0xf3, 0x4c, 0x8d, 0x77, 0x08, 0x8b, 0x47,
        0x08, 0xff, 0xc8, 0x48, 0xba, 0x15, 0x7c, 0x4a,
    };
    static const uint8_t end_segment_sig[] = {
        0x55, 0x48, 0x89, 0xe5, 0x48, 0x8b, 0x47, 0x60,
        0x8b, 0x8f, 0x90, 0x02, 0x00, 0x00, 0x48, 0x8b,
        0x97, 0x8c, 0x02, 0x00, 0x00, 0x48, 0x89, 0x50,
    };
    static const uint8_t end_segment_store_sig[] = {
        0x48, 0x89, 0x87, 0x30, 0x03, 0x00, 0x00, 0x48,
        0x89, 0x97, 0x38, 0x03, 0x00, 0x00, 0x48, 0x89,
        0x77, 0x60, 0x48, 0x89, 0x4f, 0x68, 0x5d, 0xc3,
    };
    static const uint8_t finalize_sig[] = {
        0x55, 0x48, 0x89, 0xe5, 0x41, 0x56, 0x53, 0x48,
        0x89, 0xfb, 0x4c, 0x8b, 0xb7, 0x08, 0x03, 0x00,
        0x00, 0x8b, 0x87, 0x20, 0x03, 0x00, 0x00, 0x83,
    };
    static const uint8_t ioaccel_add_sig[] = {
        0xff, 0x25, 0xa2, 0x5e, 0xa2, 0x30, 0xff, 0x25,
        0xa4, 0x5e, 0xa2, 0x30,
    };
    static const uint8_t ioaccel_reset_sig[] = {
        0xff, 0x25, 0xa8, 0x5e, 0xa2, 0x30, 0xff, 0x25,
        0xaa, 0x5e, 0xa2, 0x30,
    };

    switch (kind) {
    case AGFX_METAL_AUTHOR_KIND_BEGIN_SEGMENT:
        *sig = begin_segment_sig;
        *sig_len = sizeof(begin_segment_sig);
        return true;
    case AGFX_METAL_AUTHOR_KIND_MTL_ADD:
        *sig = mtl_add_sig;
        *sig_len = sizeof(mtl_add_sig);
        return true;
    case AGFX_METAL_AUTHOR_KIND_END_SEGMENT:
        *sig = end_segment_sig;
        *sig_len = sizeof(end_segment_sig);
        return true;
    case AGFX_METAL_AUTHOR_KIND_END_SEGMENT_STORE:
        *sig = end_segment_store_sig;
        *sig_len = sizeof(end_segment_store_sig);
        return true;
    case AGFX_METAL_AUTHOR_KIND_FINALIZE:
        *sig = finalize_sig;
        *sig_len = sizeof(finalize_sig);
        return true;
    case AGFX_METAL_AUTHOR_KIND_ALLOC_RESOURCE:
        *sig = alloc_resource_sig;
        *sig_len = sizeof(alloc_resource_sig);
        return true;
    case AGFX_METAL_AUTHOR_KIND_IOADD:
        *sig = ioaccel_add_sig;
        *sig_len = sizeof(ioaccel_add_sig);
        return true;
    case AGFX_METAL_AUTHOR_KIND_RESET:
        *sig = ioaccel_reset_sig;
        *sig_len = sizeof(ioaccel_reset_sig);
        return true;
    default:
        *sig = NULL;
        *sig_len = 0;
        return false;
    }
}

static int agfx_guest_sched_find_bytes(const uint8_t *buf, size_t buf_len,
                                       const uint8_t *needle,
                                       size_t needle_len)
{
    if (!buf || !needle || needle_len == 0 || buf_len < needle_len) {
        return -1;
    }
    for (size_t i = 0; i <= buf_len - needle_len; i++) {
        if (memcmp(buf + i, needle, needle_len) == 0) {
            return (int)i;
        }
    }
    return -1;
}

static uint64_t agfx_guest_sched_resolve_metal_author_addr(
    AppleGfxMLState *s, CPUState *cpu, uint32_t kind, const char *source)
{
    const uint8_t *sig = NULL;
    size_t sig_len = 0;
    uint64_t custom;
    uint64_t static_addr;
    uint64_t cached_addr;
    uint64_t range;
    uint64_t step;
    uint64_t max_probes;
    uint64_t probes = 0;
    uint64_t readable = 0;
    uint64_t page_probes = 0;
    uint64_t page_readable = 0;
    uint64_t attempt_seq;
    bool page_scan;

    custom = agfx_env_u64("QMU_DIAG_GUEST_SCHED_METAL_SEG_AUTHOR_ADDR", 0);
    if (custom != 0 || !agfx_guest_sched_metal_author_discover_on()) {
        return agfx_guest_sched_metal_author_addr_for_kind(kind);
    }

    static_addr = agfx_guest_sched_metal_author_default_addr_for_kind(kind);
    if (qatomic_read(&s->guest_sched_metal_author_discover_done) != 0 &&
        qatomic_read(&s->guest_sched_metal_author_discover_kind) == kind) {
        return qatomic_read(&s->guest_sched_metal_author_discover_addr);
    }

    attempt_seq = qatomic_fetch_inc(
        &s->guest_sched_metal_author_discover_attempt_seq) + 1;
    if (!cpu) {
        agfx_log(s,
                 "[apple-gfx-ml] "
                 "DIAG_GUEST_SCHED_METAL_SEG_AUTHOR_DISCOVER "
                 "state=no_cpu attempt_seq=%llu source=%s kind=%s kind_id=%u "
                 "static=0x%llx ch5_interval=%llu\n",
                 (unsigned long long)attempt_seq,
                 source ? source : "unknown",
                 agfx_guest_sched_metal_author_kind_name(kind),
                 kind,
                 (unsigned long long)static_addr,
                 (unsigned long long)qatomic_read(
                     &s->guest_sched_ch5_interval_id));
        return 0;
    }
    if (!agfx_guest_sched_metal_author_signature_for_kind(kind, &sig,
                                                          &sig_len)) {
        qatomic_set(&s->guest_sched_metal_author_discover_done, 1);
        qatomic_set(&s->guest_sched_metal_author_discover_kind, kind);
        qatomic_set(&s->guest_sched_metal_author_discover_addr, 0);
        agfx_log(s,
                 "[apple-gfx-ml] "
                 "DIAG_GUEST_SCHED_METAL_SEG_AUTHOR_DISCOVER "
                 "state=no_signature attempt_seq=%llu source=%s kind=%s "
                 "kind_id=%u static=0x%llx ch5_interval=%llu\n",
                 (unsigned long long)attempt_seq,
                 source ? source : "unknown",
                 agfx_guest_sched_metal_author_kind_name(kind),
                 kind,
                 (unsigned long long)static_addr,
                 (unsigned long long)qatomic_read(
                     &s->guest_sched_ch5_interval_id));
        return 0;
    }

    range = agfx_env_u64(
        "QMU_DIAG_GUEST_SCHED_METAL_SEG_AUTHOR_DISCOVER_RANGE",
        0x10000000ULL);
    step = agfx_env_u64(
        "QMU_DIAG_GUEST_SCHED_METAL_SEG_AUTHOR_DISCOVER_STEP", 0x1000ULL);
    if (step == 0) {
        step = 0x1000ULL;
    }
    max_probes = agfx_env_u64(
        "QMU_DIAG_GUEST_SCHED_METAL_SEG_AUTHOR_DISCOVER_MAX_PROBES",
        131073ULL);
    page_scan = agfx_guest_sched_metal_author_discover_page_scan_on();

    for (uint64_t delta = 0; delta <= range && probes < max_probes; ) {
        uint64_t candidates[2] = { static_addr + delta, 0 };
        unsigned cand_count = 1;

        if (delta != 0 && static_addr >= delta) {
            candidates[cand_count++] = static_addr - delta;
        }
        for (unsigned i = 0; i < cand_count && probes < max_probes; i++) {
            uint8_t buf[AGFX_METAL_AUTHOR_DISCOVER_SIG_MAX] = { 0 };
            uint64_t addr = candidates[i];

            if (!agfx_guest_sched_metal_author_pc_plausible(addr)) {
                continue;
            }
            probes++;
            if (cpu_memory_rw_debug(cpu, addr, buf, sig_len, 0) != 0) {
                continue;
            }
            readable++;
            if (memcmp(buf, sig, sig_len) != 0) {
                uint8_t page_buf[0x1000];
                uint64_t page_addr;
                int found_off;

                if (!page_scan) {
                    continue;
                }
                page_addr = addr & ~0xfffULL;
                page_probes++;
                if (cpu_memory_rw_debug(cpu, page_addr, page_buf,
                                        sizeof(page_buf), 0) != 0) {
                    continue;
                }
                page_readable++;
                found_off = agfx_guest_sched_find_bytes(
                    page_buf, sizeof(page_buf), sig, sig_len);
                if (found_off < 0) {
                    continue;
                }
                addr = page_addr + (uint64_t)found_off;
            } else {
                page_scan = false;
            }

            {
                const char *state = page_scan ? "found_page" : "found";

                qatomic_set(&s->guest_sched_metal_author_discover_done, 1);
                qatomic_set(&s->guest_sched_metal_author_discover_kind, kind);
                qatomic_set(&s->guest_sched_metal_author_discover_addr, addr);
                qatomic_set(&s->guest_sched_metal_author_discover_slide,
                            addr - static_addr);
                agfx_log(s,
                         "[apple-gfx-ml] "
                         "DIAG_GUEST_SCHED_METAL_SEG_AUTHOR_DISCOVER "
                         "state=%s attempt_seq=%llu source=%s kind=%s "
                         "kind_id=%u static=0x%llx addr=0x%llx "
                         "slide=0x%llx range=0x%llx step=0x%llx "
                         "probes=%llu readable=%llu page_probes=%llu "
                         "page_readable=%llu sig_len=%llu "
                         "ch5_interval=%llu\n",
                         state,
                         (unsigned long long)attempt_seq,
                         source ? source : "unknown",
                         agfx_guest_sched_metal_author_kind_name(kind),
                         kind,
                         (unsigned long long)static_addr,
                         (unsigned long long)addr,
                         (unsigned long long)(addr - static_addr),
                         (unsigned long long)range,
                         (unsigned long long)step,
                         (unsigned long long)probes,
                         (unsigned long long)readable,
                         (unsigned long long)page_probes,
                         (unsigned long long)page_readable,
                         (unsigned long long)sig_len,
                         (unsigned long long)qatomic_read(
                             &s->guest_sched_ch5_interval_id));
                return addr;
            }
        }
        if (range - delta < step) {
            break;
        }
        delta += step;
    }

    if (kind == AGFX_METAL_AUTHOR_KIND_IOADD ||
        kind == AGFX_METAL_AUTHOR_KIND_END_SEGMENT ||
        kind == AGFX_METAL_AUTHOR_KIND_END_SEGMENT_STORE ||
        kind == AGFX_METAL_AUTHOR_KIND_RESET) {
        uint64_t slide_source_static = AGFX_METAL_RESOURCE_LIST_ADD_ADDR;
        uint64_t slide_source_addr;
        uint64_t derived_addr;
        uint8_t derived_buf[AGFX_METAL_AUTHOR_DISCOVER_SIG_MAX] = { 0 };
        uint64_t derived_q0 = 0;
        uint64_t derived_q1 = 0;
        uint64_t derived_q2 = 0;
        uint64_t derived_hash = 0;
        bool derived_sig_match = false;

        slide_source_addr = agfx_guest_sched_resolve_metal_author_addr(
            s, cpu, AGFX_METAL_AUTHOR_KIND_MTL_ADD,
            "ioaccel_stub_slide_fallback");
        if (slide_source_addr != 0 && slide_source_addr >= slide_source_static) {
            derived_addr = static_addr + (slide_source_addr - slide_source_static);
            if (agfx_guest_sched_metal_author_pc_plausible(derived_addr) &&
                cpu_memory_rw_debug(cpu, derived_addr, derived_buf,
                                    sig_len, 0) == 0) {
                memcpy(&derived_q0, derived_buf, sizeof(derived_q0));
                memcpy(&derived_q1, derived_buf + sizeof(derived_q0),
                       sizeof(derived_q1));
                memcpy(&derived_q2,
                       derived_buf + 2 * sizeof(derived_q0),
                       sizeof(derived_q2));
                derived_hash = agfx_fnv1a64(derived_buf, sig_len);
                derived_sig_match = memcmp(derived_buf, sig, sig_len) == 0;
                qatomic_set(&s->guest_sched_metal_author_discover_done, 1);
                qatomic_set(&s->guest_sched_metal_author_discover_kind, kind);
                qatomic_set(&s->guest_sched_metal_author_discover_addr,
                            derived_addr);
                qatomic_set(&s->guest_sched_metal_author_discover_slide,
                            slide_source_addr - slide_source_static);
                agfx_log(s,
                         "[apple-gfx-ml] "
                         "DIAG_GUEST_SCHED_METAL_SEG_AUTHOR_DISCOVER "
                         "state=found_via_slide attempt_seq=%llu source=%s "
                         "kind=%s kind_id=%u static=0x%llx addr=0x%llx "
                         "slide=0x%llx slide_source_kind=%s "
                         "slide_source_static=0x%llx "
                         "slide_source_addr=0x%llx range=0x%llx "
                         "step=0x%llx probes=%llu readable=%llu "
                         "page_probes=%llu page_readable=%llu sig_len=%llu "
                         "derived_sig_match=%d derived_hash=0x%llx "
                         "derived_q0=0x%llx derived_q1=0x%llx "
                         "derived_q2=0x%llx ch5_interval=%llu\n",
                         (unsigned long long)attempt_seq,
                         source ? source : "unknown",
                         agfx_guest_sched_metal_author_kind_name(kind),
                         kind,
                         (unsigned long long)static_addr,
                         (unsigned long long)derived_addr,
                         (unsigned long long)
                             (slide_source_addr - slide_source_static),
                         agfx_guest_sched_metal_author_kind_name(
                             AGFX_METAL_AUTHOR_KIND_MTL_ADD),
                         (unsigned long long)slide_source_static,
                         (unsigned long long)slide_source_addr,
                         (unsigned long long)range,
                         (unsigned long long)step,
                         (unsigned long long)probes,
                         (unsigned long long)readable,
                         (unsigned long long)page_probes,
                         (unsigned long long)page_readable,
                         (unsigned long long)sig_len,
                         derived_sig_match,
                         (unsigned long long)derived_hash,
                         (unsigned long long)derived_q0,
                         (unsigned long long)derived_q1,
                         (unsigned long long)derived_q2,
                         (unsigned long long)qatomic_read(
                             &s->guest_sched_ch5_interval_id));
                return derived_addr;
            }
        }
    }

    cached_addr = 0;
    qatomic_set(&s->guest_sched_metal_author_discover_done, 1);
    qatomic_set(&s->guest_sched_metal_author_discover_kind, kind);
    qatomic_set(&s->guest_sched_metal_author_discover_addr, cached_addr);
    qatomic_set(&s->guest_sched_metal_author_discover_slide, 0);
    agfx_log(s,
             "[apple-gfx-ml] DIAG_GUEST_SCHED_METAL_SEG_AUTHOR_DISCOVER "
             "state=miss attempt_seq=%llu source=%s kind=%s kind_id=%u "
             "static=0x%llx range=0x%llx step=0x%llx probes=%llu "
             "readable=%llu page_probes=%llu page_readable=%llu "
             "max_probes=%llu sig_len=%llu ch5_interval=%llu\n",
             (unsigned long long)attempt_seq,
             source ? source : "unknown",
             agfx_guest_sched_metal_author_kind_name(kind),
             kind,
             (unsigned long long)static_addr,
             (unsigned long long)range,
             (unsigned long long)step,
             (unsigned long long)probes,
             (unsigned long long)readable,
             (unsigned long long)page_probes,
             (unsigned long long)page_readable,
             (unsigned long long)max_probes,
             (unsigned long long)sig_len,
             (unsigned long long)qatomic_read(&s->guest_sched_ch5_interval_id));
    return 0;
}

static bool agfx_guest_sched_metal_author_arm_allowed(AppleGfxMLState *s)
{
    uint64_t interval;
    uint64_t min_interval;
    uint64_t max_interval;

    if (!s) {
        return false;
    }
    interval = qatomic_read(&s->guest_sched_ch5_interval_id);
    min_interval = agfx_env_u64(
        "QMU_DIAG_GUEST_SCHED_METAL_SEG_AUTHOR_MIN_CH5", 0);
    max_interval = agfx_env_u64(
        "QMU_DIAG_GUEST_SCHED_METAL_SEG_AUTHOR_MAX_CH5", UINT64_MAX);
    return interval >= min_interval && interval <= max_interval;
}

static void agfx_guest_sched_maybe_arm_metal_header_cand_wp(
    AppleGfxMLState *s, CPUState *cpu, const char *phase, uint64_t hit_seq,
    uint32_t kind, const char *name, uint64_t header_ptr,
    const AgfxRawAuthorHeaderSummary *cand)
{
    const char *want_name;
    uint64_t env_seg;
    uint64_t env_res;
    uint64_t watch_addr;
    uint64_t watch_len;
    uint64_t max_hits;
    uint64_t cur_ch5;
    uint64_t arm_ch5;
    uint64_t max_delta;
    uint64_t arm_q0 = 0;
    uint64_t arm_q1 = 0;
    uint64_t arm_seq;
    bool arm_read_valid;
    int rc;

    if (!s || !cpu || !cand || !cand->valid ||
        !agfx_guest_sched_metal_header_cand_write_wp_on() ||
        !agfx_guest_sched_segment_header_write_wp_on() ||
        strcmp(phase ? phase : "", "entry") != 0 ||
        !agfx_guest_sched_data_ptr_plausible(header_ptr)) {
        return;
    }

    want_name = getenv("QMU_DIAG_GUEST_SCHED_METAL_HEADER_CAND_WRITE_WP_NAME");
    if (!want_name || !want_name[0]) {
        want_name = "q330";
    }
    if (strcmp(name ? name : "", want_name) != 0) {
        return;
    }

    env_seg = agfx_env_u64(
        "QMU_DIAG_GUEST_SCHED_METAL_HEADER_CAND_WRITE_WP_SEG", 3);
    env_res = agfx_env_u64(
        "QMU_DIAG_GUEST_SCHED_METAL_HEADER_CAND_WRITE_WP_RES", 0);
    if (env_seg >= cand->segment_count ||
        env_seg >= AGFX_RAW_AUTHOR_TREE_SEG_LOG_MAX ||
        env_res >= AGFX_SEGMENT_INIT_HEADER_RES_MAX) {
        return;
    }

    max_hits = agfx_env_u64(
        "QMU_DIAG_GUEST_SCHED_SEGMENT_HEADER_WRITE_WP_MAX", 16);
    if (max_hits != 0 &&
        qatomic_read(&s->guest_sched_segment_header_wp_hit_seq) >= max_hits) {
        return;
    }

    cur_ch5 = qatomic_read(&s->guest_sched_ch5_interval_id);
    max_delta = agfx_env_u64(
        "QMU_DIAG_GUEST_SCHED_SEGMENT_HEADER_WRITE_WP_MAX_CH5_DELTA", 4);
    if (qatomic_read(&s->guest_sched_segment_header_wp_armed) != 0) {
        arm_ch5 =
            qatomic_read(&s->guest_sched_segment_header_wp_arm_ch5_interval);
        if (cur_ch5 <= arm_ch5 + max_delta) {
            return;
        }

        watch_addr = qatomic_read(&s->guest_sched_segment_header_wp_addr);
        watch_len = qatomic_read(&s->guest_sched_segment_header_wp_len);
        rc = agfx_guest_sched_remove_hw_watchpoint_all(watch_addr, watch_len);
        qatomic_set(&s->guest_sched_segment_header_wp_armed, 0);
        qatomic_set(&s->guest_sched_segment_header_wp_addr, 0);
        qatomic_set(&s->guest_sched_segment_header_wp_len, 0);
        agfx_log(s,
                 "[apple-gfx-ml] "
                 "DIAG_GUEST_SCHED_METAL_HEADER_CAND_WP_STALE_REMOVE "
                 "hit_seq=%llu old_addr=0x%llx old_len=%llu "
                 "arm_ch5=%llu cur_ch5=%llu max_delta=%llu rc=%d\n",
                 (unsigned long long)hit_seq,
                 (unsigned long long)watch_addr,
                 (unsigned long long)watch_len,
                 (unsigned long long)arm_ch5,
                 (unsigned long long)cur_ch5,
                 (unsigned long long)max_delta,
                 rc);
    }

    watch_len = agfx_env_u64(
        "QMU_DIAG_GUEST_SCHED_SEGMENT_HEADER_WRITE_WP_LEN",
        sizeof(uint32_t));
    if (watch_len == 0 || watch_len > 0x40) {
        watch_len = sizeof(uint32_t);
    }
    watch_addr = header_ptr + 0x18ULL + env_seg * 0x58ULL + env_res * 4ULL;
    if (!agfx_guest_sched_data_ptr_plausible(watch_addr) ||
        qatomic_cmpxchg(&s->guest_sched_segment_header_wp_armed, 0, 1) != 0) {
        return;
    }

    arm_read_valid =
        cpu_memory_rw_debug(cpu, watch_addr, (uint8_t *)&arm_q0,
                            sizeof(arm_q0), 0) == 0 &&
        cpu_memory_rw_debug(cpu, watch_addr + sizeof(arm_q0),
                            (uint8_t *)&arm_q1, sizeof(arm_q1), 0) == 0;
    arm_seq = qatomic_fetch_inc(&s->guest_sched_segment_header_wp_arm_seq) + 1;
    qatomic_set(&s->guest_sched_segment_header_wp_addr, watch_addr);
    qatomic_set(&s->guest_sched_segment_header_wp_len, watch_len);
    qatomic_set(&s->guest_sched_segment_header_wp_hits_in_arm, 0);
    qatomic_set(&s->guest_sched_segment_header_wp_arm_init_hit_seq, hit_seq);
    qatomic_set(&s->guest_sched_segment_header_wp_arm_ch5_interval, cur_ch5);
    qatomic_set(&s->guest_sched_segment_header_wp_header, header_ptr);
    qatomic_set(&s->guest_sched_segment_header_wp_kernel_addr, watch_addr);
    qatomic_set(&s->guest_sched_segment_header_wp_kernel_header, header_ptr);
    qatomic_set(&s->guest_sched_segment_header_wp_client_base, 0);
    qatomic_set(&s->guest_sched_segment_header_wp_client_header, 0);
    qatomic_set(&s->guest_sched_segment_header_wp_header_off,
                header_ptr & 0xfffULL);
    qatomic_set(&s->guest_sched_segment_header_wp_arm_q0, arm_q0);
    qatomic_set(&s->guest_sched_segment_header_wp_arm_q1, arm_q1);
    qatomic_set(&s->guest_sched_segment_header_wp_seg_index, env_seg);
    qatomic_set(&s->guest_sched_segment_header_wp_res_index, env_res);
    qatomic_set(&s->guest_sched_segment_header_wp_res_id,
                cand->watched_id[env_res]);

    rc = agfx_guest_sched_insert_hw_watchpoint_all(watch_addr, watch_len);
    if (rc != 0) {
        qatomic_set(&s->guest_sched_segment_header_wp_armed, 0);
        qatomic_set(&s->guest_sched_segment_header_wp_addr, 0);
        qatomic_set(&s->guest_sched_segment_header_wp_len, 0);
    }

    agfx_log(s,
             "[apple-gfx-ml] DIAG_GUEST_SCHED_METAL_HEADER_CAND_WP_ARM "
             "phase=%s hit_seq=%llu state=%s arm_seq=%llu kind=%s "
             "kind_id=%u name=%s header=0x%llx watch_addr=0x%llx "
             "watch_len=%llu seg=%llu res=%llu arm_res_id=%u "
             "arm_read_valid=%d arm_q0=0x%llx arm_q1=0x%llx "
             "slot3=%u hash=0x%llx total=%u segs=%u rc=%d ch5=%llu\n",
             phase ? phase : "unknown",
             (unsigned long long)hit_seq,
             rc == 0 ? "armed" : "failed",
             (unsigned long long)arm_seq,
             agfx_guest_sched_metal_author_kind_name(kind),
             kind,
             name ? name : "-",
             (unsigned long long)header_ptr,
             (unsigned long long)watch_addr,
             (unsigned long long)watch_len,
             (unsigned long long)env_seg,
             (unsigned long long)env_res,
             cand->watched_id[env_res],
             arm_read_valid,
             (unsigned long long)arm_q0,
             (unsigned long long)arm_q1,
             cand->first_id[3],
             (unsigned long long)cand->hash,
             cand->total_resources,
             cand->segment_count,
             rc,
             (unsigned long long)cur_ch5);
}

static void agfx_guest_sched_log_metal_author_snapshot(
    AppleGfxMLState *s, CPUState *cpu, const char *phase, uint64_t hit_seq,
    uint32_t kind, uint64_t pc, uint64_t arg0, uint64_t arg1,
    uint64_t arg2, uint64_t arg3, uint64_t ret_addr)
{
    uint64_t list_ptr = 0;
    uint64_t storage_ptr = 0;
    uint64_t raw_base = 0;
    uint64_t list_q[8] = { 0 };
    uint64_t storage_q28 = 0;
    uint64_t storage_q48 = 0;
    uint64_t storage_q50 = 0;
    uint64_t storage_q58 = 0;
    uint64_t storage_q60 = 0;
    uint64_t storage_q68 = 0;
    uint64_t storage_q70 = 0;
    uint64_t storage_q300 = 0;
    uint64_t storage_q308 = 0;
    uint64_t storage_q310 = 0;
    uint64_t storage_q330 = 0;
    uint64_t storage_q338 = 0;
    uint64_t storage_q2e0 = 0;
    uint64_t storage_q2e8 = 0;
    uint32_t storage_u318 = 0xffffffffu;
    uint32_t storage_u320 = 0xffffffffu;
    uint32_t storage_u340 = 0xffffffffu;
    uint64_t header_q0 = 0;
    uint64_t header_q8 = 0;
    uint64_t header_q10 = 0;
    uint64_t entry_q0 = 0;
    uint64_t entry_q8 = 0;
    uint32_t raw_id[8] = { 0 };
    uint32_t entry_id[8] = { 0 };
    uint16_t raw_flag[8] = { 0 };
    uint16_t raw_count = 0xffffu;
    bool list_valid = false;
    bool storage_valid = false;
    bool header_valid = false;
    bool entry_valid = false;
    bool raw_valid = false;

    if (!s || !cpu) {
        return;
    }

    switch (kind) {
    case AGFX_METAL_AUTHOR_KIND_BEGIN_SEGMENT:
    case AGFX_METAL_AUTHOR_KIND_END_SEGMENT:
    case AGFX_METAL_AUTHOR_KIND_END_SEGMENT_STORE:
    case AGFX_METAL_AUTHOR_KIND_FINALIZE:
    case AGFX_METAL_AUTHOR_KIND_ALLOC_RESOURCE:
        storage_ptr = arg0;
        list_ptr = arg0 + 0x70;
        break;
    case AGFX_METAL_AUTHOR_KIND_MTL_ADD:
    case AGFX_METAL_AUTHOR_KIND_IOADD:
    case AGFX_METAL_AUTHOR_KIND_RESET:
    case AGFX_METAL_AUTHOR_KIND_CUSTOM:
    default:
        list_ptr = arg0;
        if (arg0 > 0x70) {
            storage_ptr = arg0 - 0x70;
        }
        break;
    }

    if (agfx_guest_sched_data_ptr_plausible(list_ptr)) {
        list_valid = cpu_memory_rw_debug(cpu, list_ptr, (uint8_t *)list_q,
                                         sizeof(list_q), 0) == 0;
    }

    if (agfx_guest_sched_data_ptr_plausible(storage_ptr)) {
        bool ok = true;

        ok &= agfx_guest_sched_read_data_u64(cpu, storage_ptr + 0x28,
                                             &storage_q28);
        ok &= agfx_guest_sched_read_data_u64(cpu, storage_ptr + 0x48,
                                             &storage_q48);
        ok &= agfx_guest_sched_read_data_u64(cpu, storage_ptr + 0x50,
                                             &storage_q50);
        ok &= agfx_guest_sched_read_data_u64(cpu, storage_ptr + 0x58,
                                             &storage_q58);
        ok &= agfx_guest_sched_read_data_u64(cpu, storage_ptr + 0x60,
                                             &storage_q60);
        ok &= agfx_guest_sched_read_data_u64(cpu, storage_ptr + 0x68,
                                             &storage_q68);
        (void)agfx_guest_sched_read_data_u64(cpu, storage_ptr + 0x70,
                                             &storage_q70);
        (void)agfx_guest_sched_read_data_u64(cpu, storage_ptr + 0x300,
                                             &storage_q300);
        (void)agfx_guest_sched_read_data_u64(cpu, storage_ptr + 0x308,
                                             &storage_q308);
        (void)agfx_guest_sched_read_data_u64(cpu, storage_ptr + 0x310,
                                             &storage_q310);
        (void)agfx_guest_sched_read_data_u32(cpu, storage_ptr + 0x318,
                                             &storage_u318);
        (void)agfx_guest_sched_read_data_u32(cpu, storage_ptr + 0x320,
                                             &storage_u320);
        (void)agfx_guest_sched_read_data_u64(cpu, storage_ptr + 0x330,
                                             &storage_q330);
        (void)agfx_guest_sched_read_data_u64(cpu, storage_ptr + 0x338,
                                             &storage_q338);
        (void)agfx_guest_sched_read_data_u32(cpu, storage_ptr + 0x340,
                                             &storage_u340);
        (void)agfx_guest_sched_read_data_u64(cpu, storage_ptr + 0x2e0,
                                             &storage_q2e0);
        (void)agfx_guest_sched_read_data_u64(cpu, storage_ptr + 0x2e8,
                                             &storage_q2e8);
        storage_valid = ok;
    }

    if (agfx_guest_sched_data_ptr_plausible(storage_q58)) {
        header_valid =
            agfx_guest_sched_read_data_u64(cpu, storage_q58, &header_q0) &&
            agfx_guest_sched_read_data_u64(cpu, storage_q58 + 8, &header_q8) &&
            agfx_guest_sched_read_data_u64(cpu, storage_q58 + 0x10,
                                           &header_q10);
    }
    if (agfx_guest_sched_data_ptr_plausible(storage_q60)) {
        entry_valid =
            agfx_guest_sched_read_data_u64(cpu, storage_q60, &entry_q0) &&
            agfx_guest_sched_read_data_u64(cpu, storage_q60 + 8, &entry_q8);
        for (unsigned i = 0; i < 8; i++) {
            (void)agfx_guest_sched_read_data_u32(
                cpu, storage_q60 + (uint64_t)i * sizeof(uint32_t),
                &entry_id[i]);
        }
    }

    if (kind == AGFX_METAL_AUTHOR_KIND_RESET &&
        agfx_guest_sched_data_ptr_plausible(arg1)) {
        raw_base = arg1;
    } else if (agfx_guest_sched_data_ptr_plausible(storage_q60)) {
        raw_base = storage_q60 + 0x18;
    }

    if (agfx_guest_sched_data_ptr_plausible(raw_base)) {
        raw_valid = true;
        for (unsigned i = 0; i < 8; i++) {
            raw_valid &= agfx_guest_sched_read_data_u32(
                cpu, raw_base + (uint64_t)i * sizeof(uint32_t),
                &raw_id[i]);
            (void)agfx_guest_sched_read_data_u16(
                cpu, raw_base + 0x48ULL + (uint64_t)i * sizeof(uint16_t),
                &raw_flag[i]);
        }
        (void)agfx_guest_sched_read_data_u16(cpu, raw_base + 0x56,
                                             &raw_count);
    }

    agfx_log(s,
             "[apple-gfx-ml] DIAG_GUEST_SCHED_METAL_SEG_AUTHOR_SNAPSHOT "
             "phase=%s hit_seq=%llu kind=%s kind_id=%u pc=0x%llx "
             "ch5_interval=%llu arg0=0x%llx arg1=0x%llx "
             "arg2=0x%llx arg3=0x%llx ret=0x%llx "
             "list=0x%llx list_valid=%d storage=0x%llx "
             "storage_valid=%d raw_base=0x%llx raw_valid=%d\n",
             phase ? phase : "unknown",
             (unsigned long long)hit_seq,
             agfx_guest_sched_metal_author_kind_name(kind),
             kind,
             (unsigned long long)pc,
             (unsigned long long)qatomic_read(&s->guest_sched_ch5_interval_id),
             (unsigned long long)arg0,
             (unsigned long long)arg1,
             (unsigned long long)arg2,
             (unsigned long long)arg3,
             (unsigned long long)ret_addr,
             (unsigned long long)list_ptr,
             list_valid,
             (unsigned long long)storage_ptr,
             storage_valid,
             (unsigned long long)raw_base,
             raw_valid);

    agfx_log(s,
             "[apple-gfx-ml] DIAG_GUEST_SCHED_METAL_SEG_AUTHOR_LIST "
             "phase=%s hit_seq=%llu list=0x%llx "
             "q0=0x%llx q1=0x%llx q2=0x%llx q3=0x%llx "
             "q4=0x%llx q5=0x%llx q6=0x%llx q7=0x%llx\n",
             phase ? phase : "unknown",
             (unsigned long long)hit_seq,
             (unsigned long long)list_ptr,
             (unsigned long long)list_q[0],
             (unsigned long long)list_q[1],
             (unsigned long long)list_q[2],
             (unsigned long long)list_q[3],
             (unsigned long long)list_q[4],
             (unsigned long long)list_q[5],
             (unsigned long long)list_q[6],
             (unsigned long long)list_q[7]);

    agfx_log(s,
             "[apple-gfx-ml] DIAG_GUEST_SCHED_METAL_SEG_AUTHOR_STORAGE "
             "phase=%s hit_seq=%llu storage=0x%llx "
             "q28=0x%llx q48=0x%llx q50=0x%llx q58=0x%llx "
             "q60=0x%llx q68=0x%llx q70=0x%llx q300=0x%llx "
             "q308=0x%llx q310=0x%llx u318=%u u320=%u "
             "q330=0x%llx q338=0x%llx u340=%u "
             "q2e0=0x%llx q2e8=0x%llx "
             "header_valid=%d h0=0x%llx h8=0x%llx h10=0x%llx "
             "entry_valid=%d e0=0x%llx e8=0x%llx "
             "entry_ids=%u,%u,%u,%u,%u,%u,%u,%u\n",
             phase ? phase : "unknown",
             (unsigned long long)hit_seq,
             (unsigned long long)storage_ptr,
             (unsigned long long)storage_q28,
             (unsigned long long)storage_q48,
             (unsigned long long)storage_q50,
             (unsigned long long)storage_q58,
             (unsigned long long)storage_q60,
             (unsigned long long)storage_q68,
             (unsigned long long)storage_q70,
             (unsigned long long)storage_q300,
             (unsigned long long)storage_q308,
             (unsigned long long)storage_q310,
             storage_u318,
             storage_u320,
             (unsigned long long)storage_q330,
             (unsigned long long)storage_q338,
             storage_u340,
             (unsigned long long)storage_q2e0,
             (unsigned long long)storage_q2e8,
             header_valid,
             (unsigned long long)header_q0,
             (unsigned long long)header_q8,
             (unsigned long long)header_q10,
             entry_valid,
             (unsigned long long)entry_q0,
             (unsigned long long)entry_q8,
             entry_id[0], entry_id[1], entry_id[2], entry_id[3],
             entry_id[4], entry_id[5], entry_id[6], entry_id[7]);

    agfx_log(s,
             "[apple-gfx-ml] DIAG_GUEST_SCHED_METAL_SEG_AUTHOR_RAW "
             "phase=%s hit_seq=%llu raw_base=0x%llx raw_count=%u "
             "ids=%u,%u,%u,%u,%u,%u,%u,%u "
             "flags=0x%x,0x%x,0x%x,0x%x,0x%x,0x%x,0x%x,0x%x\n",
             phase ? phase : "unknown",
             (unsigned long long)hit_seq,
             (unsigned long long)raw_base,
             raw_count,
             raw_id[0], raw_id[1], raw_id[2], raw_id[3],
             raw_id[4], raw_id[5], raw_id[6], raw_id[7],
             raw_flag[0], raw_flag[1], raw_flag[2], raw_flag[3],
             raw_flag[4], raw_flag[5], raw_flag[6], raw_flag[7]);

    if (storage_valid) {
        const struct {
            const char *name;
            uint64_t ptr;
        } candidates[] = {
            { "q58", storage_q58 },
            { "q60", storage_q60 },
            { "q68", storage_q68 },
            { "q308", storage_q308 },
            { "q330", storage_q330 },
            { "q338", storage_q338 },
        };
        unsigned watched_seg = (unsigned)agfx_env_u64(
            "QMU_DIAG_GUEST_SCHED_METAL_SEG_AUTHOR_HEADER_CAND_SEG", 3);

        for (unsigned ci = 0; ci < G_N_ELEMENTS(candidates); ci++) {
            AgfxRawAuthorHeaderSummary cand = { 0 };
            bool cand_valid;

            if (candidates[ci].ptr == 0 ||
                !agfx_guest_sched_data_ptr_plausible(candidates[ci].ptr)) {
                continue;
            }

            cand_valid = agfx_guest_sched_probe_raw_author_header(
                cpu, candidates[ci].ptr, watched_seg, &cand);
            agfx_log(s,
                     "[apple-gfx-ml] "
                     "DIAG_GUEST_SCHED_METAL_SEG_AUTHOR_HEADER_CAND "
                     "phase=%s hit_seq=%llu kind=%s kind_id=%u "
                     "name=%s ptr=0x%llx valid=%d watched_seg=%u "
                     "hash=0x%llx q0=0x%llx q1=0x%llx "
                     "len08=%u len0c=%u state0f=0x%x total=%u segs=%u "
                     "first_ids=%u,%u,%u,%u,%u,%u,%u,%u "
                     "watched_rcount=%u "
                     "watched_ids=%u,%u,%u,%u,%u,%u,%u,%u "
                     "watched_flags=0x%x,0x%x,0x%x,0x%x,"
                     "0x%x,0x%x,0x%x,0x%x\n",
                     phase ? phase : "unknown",
                     (unsigned long long)hit_seq,
                     agfx_guest_sched_metal_author_kind_name(kind),
                     kind,
                     candidates[ci].name,
                     (unsigned long long)candidates[ci].ptr,
                     cand_valid,
                     watched_seg,
                     (unsigned long long)cand.hash,
                     (unsigned long long)cand.q0,
                     (unsigned long long)cand.q1,
                     cand.len08,
                     cand.len0c,
                     cand.state0f,
                     cand.total_resources,
                     cand.segment_count,
                     cand.first_id[0], cand.first_id[1],
                     cand.first_id[2], cand.first_id[3],
                     cand.first_id[4], cand.first_id[5],
                     cand.first_id[6], cand.first_id[7],
                     cand.watched_rcount,
                     cand.watched_id[0], cand.watched_id[1],
                     cand.watched_id[2], cand.watched_id[3],
                     cand.watched_id[4], cand.watched_id[5],
                     cand.watched_id[6], cand.watched_id[7],
                     cand.watched_flag[0], cand.watched_flag[1],
                     cand.watched_flag[2], cand.watched_flag[3],
                     cand.watched_flag[4], cand.watched_flag[5],
                     cand.watched_flag[6], cand.watched_flag[7]);
            agfx_guest_sched_maybe_arm_metal_header_cand_wp(
                s, cpu, phase, hit_seq, kind, candidates[ci].name,
                candidates[ci].ptr, &cand);
        }
    }

    if (kind == AGFX_METAL_AUTHOR_KIND_MTL_ADD && list_valid) {
        uint64_t list_q8 = 0;
        uint64_t list_q9 = 0;
        uint64_t table_q[8] = { 0 };
        uint64_t chunk_q[8] = { 0 };
        uint64_t resource_q[8] = { 0 };
        uint64_t hash_value = arg1 * 0x9e3779b97f4a7c15ULL;
        uint32_t capacity = (uint32_t)(list_q[1] & 0xffffffffu);
        uint32_t shift = (uint32_t)((list_q[1] >> 32) & 0xffu);
        uint32_t index0 = UINT32_MAX;
        uint32_t table_nonzero = 0;
        uint32_t chunk_nonzero = 0;
        uint32_t resource_nonzero = 0;
        uint64_t table_hash = 0;
        uint64_t chunk_hash = 0;
        uint64_t resource_hash = 0;
        bool table_valid = false;
        bool chunk_valid = false;
        bool resource_valid = false;

        (void)agfx_guest_sched_read_data_u64(cpu, list_ptr + 0x40, &list_q8);
        (void)agfx_guest_sched_read_data_u64(cpu, list_ptr + 0x48, &list_q9);
        hash_value >>= ((uint8_t)(-shift) & 0x3f);
        if (capacity != 0) {
            index0 = (uint32_t)hash_value & (capacity - 1u);
        }

        if (agfx_guest_sched_data_ptr_plausible(list_q[4]) &&
            cpu_memory_rw_debug(cpu, list_q[4], (uint8_t *)table_q,
                                sizeof(table_q), 0) == 0) {
            table_valid = true;
            table_hash = agfx_fnv1a64((const uint8_t *)table_q,
                                      sizeof(table_q));
            for (unsigned i = 0; i < 8; i++) {
                if (table_q[i] != 0) {
                    table_nonzero++;
                }
            }
        }
        if (agfx_guest_sched_data_ptr_plausible(list_q[6]) &&
            cpu_memory_rw_debug(cpu, list_q[6], (uint8_t *)chunk_q,
                                sizeof(chunk_q), 0) == 0) {
            chunk_valid = true;
            chunk_hash = agfx_fnv1a64((const uint8_t *)chunk_q,
                                      sizeof(chunk_q));
            for (unsigned i = 0; i < 8; i++) {
                if (chunk_q[i] != 0) {
                    chunk_nonzero++;
                }
            }
        }
        if (agfx_guest_sched_data_ptr_plausible(arg1) &&
            cpu_memory_rw_debug(cpu, arg1, (uint8_t *)resource_q,
                                sizeof(resource_q), 0) == 0) {
            resource_valid = true;
            resource_hash = agfx_fnv1a64((const uint8_t *)resource_q,
                                         sizeof(resource_q));
            for (unsigned i = 0; i < 8; i++) {
                if (resource_q[i] != 0) {
                    resource_nonzero++;
                }
            }
        }

        agfx_log(s,
                 "[apple-gfx-ml] DIAG_GUEST_SCHED_METAL_SEG_AUTHOR_MTL_LIST "
                 "phase=%s hit_seq=%llu list=0x%llx resource=0x%llx "
                 "capacity=%u shift=%u hash=0x%llx index0=%u "
                 "bitmap=0x%llx hash_table=0x%llx entries=0x%llx "
                 "count=%llu chunk_entries=0x%llx chunk_prev=0x%llx "
                 "chunk_cap_q8=0x%llx q9=0x%llx table_valid=%d "
                 "table_nonzero=%u table_hash=0x%llx "
                 "t0=0x%llx t1=0x%llx t2=0x%llx t3=0x%llx "
                 "t4=0x%llx t5=0x%llx t6=0x%llx t7=0x%llx "
                 "chunk_valid=%d chunk_nonzero=%u chunk_hash=0x%llx "
                 "c0=0x%llx c1=0x%llx c2=0x%llx c3=0x%llx "
                 "c4=0x%llx c5=0x%llx c6=0x%llx c7=0x%llx\n",
                 phase ? phase : "unknown",
                 (unsigned long long)hit_seq,
                 (unsigned long long)list_ptr,
                 (unsigned long long)arg1,
                 capacity,
                 shift,
                 (unsigned long long)hash_value,
                 index0,
                 (unsigned long long)list_q[2],
                 (unsigned long long)list_q[3],
                 (unsigned long long)list_q[4],
                 (unsigned long long)list_q[5],
                 (unsigned long long)list_q[6],
                 (unsigned long long)list_q[7],
                 (unsigned long long)list_q8,
                 (unsigned long long)list_q9,
                 table_valid,
                 table_nonzero,
                 (unsigned long long)table_hash,
                 (unsigned long long)table_q[0],
                 (unsigned long long)table_q[1],
                 (unsigned long long)table_q[2],
                 (unsigned long long)table_q[3],
                 (unsigned long long)table_q[4],
                 (unsigned long long)table_q[5],
                 (unsigned long long)table_q[6],
                 (unsigned long long)table_q[7],
                 chunk_valid,
                 chunk_nonzero,
                 (unsigned long long)chunk_hash,
                 (unsigned long long)chunk_q[0],
                 (unsigned long long)chunk_q[1],
                 (unsigned long long)chunk_q[2],
                 (unsigned long long)chunk_q[3],
                 (unsigned long long)chunk_q[4],
                 (unsigned long long)chunk_q[5],
                 (unsigned long long)chunk_q[6],
                 (unsigned long long)chunk_q[7]);

        agfx_log(s,
                 "[apple-gfx-ml] DIAG_GUEST_SCHED_METAL_SEG_AUTHOR_RESOURCE "
                 "phase=%s hit_seq=%llu resource=0x%llx valid=%d "
                 "nonzero=%u hash=0x%llx "
                 "q0=0x%llx q1=0x%llx q2=0x%llx q3=0x%llx "
                 "q4=0x%llx q5=0x%llx q6=0x%llx q7=0x%llx\n",
                 phase ? phase : "unknown",
                 (unsigned long long)hit_seq,
                 (unsigned long long)arg1,
                 resource_valid,
                 resource_nonzero,
                 (unsigned long long)resource_hash,
                 (unsigned long long)resource_q[0],
                 (unsigned long long)resource_q[1],
                 (unsigned long long)resource_q[2],
                 (unsigned long long)resource_q[3],
                 (unsigned long long)resource_q[4],
                 (unsigned long long)resource_q[5],
                 (unsigned long long)resource_q[6],
                 (unsigned long long)resource_q[7]);
    }
}

static void agfx_guest_sched_rearm_metal_author_target(
    AppleGfxMLState *s, CPUState *cpu, const char *source, uint64_t source_seq)
{
    uint64_t bp_addr;
    uint64_t arm_seq;
    uint64_t max_hits;
    int rc;

    if (!s || !cpu || !agfx_guest_sched_metal_author_on() ||
        !agfx_guest_sched_metal_author_arm_allowed(s)) {
        return;
    }

    max_hits = agfx_guest_sched_metal_author_max_hits();
    if (max_hits != 0 &&
        qatomic_read(&s->guest_sched_metal_author_bp_hit_seq) >= max_hits) {
        return;
    }

    bp_addr = qatomic_read(&s->guest_sched_metal_author_bp_addr);
    if (!agfx_guest_sched_metal_author_pc_plausible(bp_addr) ||
        qatomic_read(&s->guest_sched_metal_author_return_bp_armed) != 0) {
        return;
    }

    if (qatomic_cmpxchg(&s->guest_sched_metal_author_bp_armed, 0, 1) != 0) {
        return;
    }

    arm_seq = qatomic_fetch_inc(&s->guest_sched_metal_author_bp_arm_seq) + 1;
    qatomic_set(&s->guest_sched_metal_author_bp_arm_ch5_interval,
                qatomic_read(&s->guest_sched_ch5_interval_id));
    rc = agfx_guest_sched_insert_hw_breakpoint_all(bp_addr);
    if (rc != 0) {
        qatomic_set(&s->guest_sched_metal_author_bp_armed, 0);
    }

    agfx_log(s,
             "[apple-gfx-ml] DIAG_GUEST_SCHED_METAL_SEG_AUTHOR_BP_REARM "
             "source=%s source_seq=%llu state=%s arm_seq=%llu "
             "kind=%s bp=0x%llx rc=%d ch5_interval=%llu hit_seq=%llu\n",
             source ? source : "unknown",
             (unsigned long long)source_seq,
             rc == 0 ? "armed" : "failed",
             (unsigned long long)arm_seq,
             agfx_guest_sched_metal_author_kind_name(
                 qatomic_read(&s->guest_sched_metal_author_kind)),
             (unsigned long long)bp_addr,
             rc,
             (unsigned long long)qatomic_read(&s->guest_sched_ch5_interval_id),
             (unsigned long long)qatomic_read(
                 &s->guest_sched_metal_author_bp_hit_seq));
}

