    arm_seq = qatomic_fetch_inc(&s->guest_sched_pcb_call_bp_arm_seq) + 1;
    qatomic_set(&s->guest_sched_pcb_call_bp_base, iogpu_base);
    qatomic_set(&s->guest_sched_pcb_call_bp_addr, bp_addr);
