static void agfx_guest_sched_maybe_arm_pcb_call_bp_early(
    AppleGfxMLState *s, CPUState *cpu, uint64_t callsite_seq,
    const char *where, uint64_t offset, uint64_t value,
    const AgfxGuestSchedCapture *cap)
{
    uint64_t apv_base;
    uint64_t apv_entry;
    const char *apv_base_source = "none";

    if (!s || !cpu || !cap || !agfx_guest_sched_pcb_call_bp_early_on() ||
        strcmp(where, "caller_write_enqueue") != 0 ||
        offset != PVG_REG_KICK) {
        return;
    }

    if (!agfx_guest_sched_apv_base_for_author_bp(
            s, cap, true, &apv_base, &apv_entry, &apv_base_source)) {
        return;
    }

    agfx_guest_sched_maybe_arm_pcb_call_bp(
        s, cpu, apv_base, apv_base_source, callsite_seq);
}

