    uint64_t res_refa0[AGFX_EXEC3_AUTHOR_SEG_MAX] = { 0 };
    uint32_t res_id[AGFX_EXEC3_AUTHOR_SEG_MAX] = { 0 };
    uint32_t res_type[AGFX_EXEC3_AUTHOR_SEG_MAX] = { 0 };
    uint32_t res_flags[AGFX_EXEC3_AUTHOR_SEG_MAX] = { 0 };
    uint32_t res_index[AGFX_EXEC3_AUTHOR_SEG_MAX] = { 0 };
    uint8_t res_dirty188[AGFX_EXEC3_AUTHOR_SEG_MAX] = { 0 };
    bool res_valid[AGFX_EXEC3_AUTHOR_SEG_MAX] = { 0 };
