        ok_count = cpu_memory_rw_debug(cpu, resource_list_ptr + 0x0c,
                                       (uint8_t *)&res_count,
                                       sizeof(res_count), 0) == 0;
        ok_table = cpu_memory_rw_debug(cpu, resource_list_ptr + 0x58,
                                       (uint8_t *)&res_entries_ptr,
                                       sizeof(res_entries_ptr), 0) == 0;
        ok_c0 = cpu_memory_rw_debug(cpu, resource_list_ptr + 0xc0,
                                    (uint8_t *)&res_c0,
                                    sizeof(res_c0), 0) == 0;
        reslist_meta_valid = ok_count && ok_table && ok_c0;
