    uint64_t workq_desc_ptr = 0;
    uint64_t workq_desc_vtable = 0;
    uint64_t workq_desc_vt140 = 0;
    uint64_t workq_desc_vt148 = 0;
    uint64_t workq_desc_vt158 = 0;
